cd /workspace && python3 << 'EOF' > /tmp/contract_summary.txt
import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)

def summarize_schema(s, depth=0, seen=None):
    seen = seen or set()
    if isinstance(s, dict):
        if '$ref' in s:
            return s['$ref'].split('/')[-1]
        t = s.get('type')
        if t == 'object':
            props = s.get('properties', {})
            req = s.get('required', [])
            out = '{'
            parts=[]
            for k,v in props.items():
                r = '?' if k not in req else ''
                parts.append(f'{k}{r}: {summarize_schema(v, depth+1, seen)}')
            out += ', '.join(parts)
            if s.get('additionalProperties') is False:
                out += ' (noExtra)'
            return out+'}'
        elif t == 'array':
            return f'[{summarize_schema(s.get("items"), depth+1, seen)}]'
        else:
            enum = s.get('enum')
            if enum:
                return f'{t}({",".join(map(str,enum))})'
            return t or 'any'
    return str(s)

def find_schema(name):
    return spec['components']['schemas'].get(name)

for path in sorted(spec['paths'].keys()):
    for m in ('get','post','put','patch','delete'):
        if m not in spec['paths'][path]: continue
        op = spec['paths'][path][m]
        print(f'### {m.upper()} {path}  [{op["operationId"]}]')
        rb = op.get('requestBody')
        if rb:
            sch = rb['content']['application/json']['schema']
            print('  REQ:', summarize_schema(sch))
        print('  Responses:')
        for code, resp in op['responses'].items():
            sch = resp.get('content',{}).get('application/json',{}).get('schema')
            if sch:
                print(f'    {code}: {summarize_schema(sch)}')
        print()
EOF
