import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

def summarize_schema(s, depth=0, resolving=None):
    resolving = resolving or set()
    if isinstance(s, dict):
        if '$ref' in s:
            name = s['$ref'].split('/')[-1]
            if name in resolving:
                return f'<{name}>'
            return name
        t = s.get('type')
        if t == 'object':
            props = s.get('properties', {})
            req = s.get('required', [])
            parts=[]
            for k,v in props.items():
                r = '?' if k not in req else ''
                parts.append(f'{k}{r}: {summarize_schema(v, depth+1, resolving)}')
            out = '{' + ', '.join(parts)
            if s.get('additionalProperties') is False:
                out += ' (noExtra)'
            elif s.get('additionalProperties') is True:
                out += ' (extraOk)'
            elif isinstance(s.get('additionalProperties'), dict):
                out += ' (extra:any)'
            return out+'}'
        elif t == 'array':
            return f'[{summarize_schema(s.get("items"), depth+1, resolving)}]'
        else:
            enum = s.get('enum')
            fmt = s.get('format')
            if enum:
                return f'{t}/{fmt}({",".join(map(str,enum))})'
            return f'{t}/{fmt}' if fmt else (t or 'any')
    return str(s)

def expand(name, seen=None):
    seen = seen or set()
    if name in seen:
        return f'<recursive {name}>'
    seen = seen | {name}
    s = spec['components']['schemas'].get(name)
    if s is None:
        return '???'
    return summarize_schema(s, 0, seen)

for name in sorted(spec['components']['schemas'].keys()):
    print(f'### {name}')
    print('  ', expand(name))
    print()

