const resetDropSQL = `
DROP TABLE IF EXISTS meta CASCADE;
DROP TABLE IF EXISTS serviceability_versions CASCADE;
DROP TABLE IF EXISTS realtime_events CASCADE;
DROP TABLE IF EXISTS audit_log CASCADE;
DROP TABLE IF EXISTS idempotency_keys CASCADE;
DROP TABLE IF EXISTS handling_checkpoints CASCADE;
DROP TABLE IF EXISTS worker_locations CASCADE;
DROP TABLE IF EXISTS capacity_reservations CASCADE;
DROP TABLE IF EXISTS handoffs CASCADE;
DROP TABLE IF EXISTS assignments CASCADE;
DROP TABLE IF EXISTS journey_stops CASCADE;
DROP TABLE IF EXISTS journeys CASCADE;
DROP TABLE IF EXISTS samples CASCADE;
DROP TABLE IF EXISTS requests CASCADE;
DROP TABLE IF EXISTS capacity_pools CASCADE;
DROP TABLE IF EXISTS connections CASCADE;
DROP TABLE IF EXISTS laboratory_acceptance CASCADE;
DROP TABLE IF EXISTS locations CASCADE;
DROP TABLE IF EXISTS sample_types CASCADE;
DROP TABLE IF EXISTS sessions CASCADE;
DROP TABLE IF EXISTS certifications CASCADE;
DROP TABLE IF EXISTS users CASCADE;
`

func openDB(ctx context.Context) error {
	dsn := envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable")
	p, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return fmt.Errorf("pgxpool: %w", err)
	}
	pool = p

	redisURL := envOr("REDIS_URL", "redis://127.0.0.1:6379/0")
	opt, err := redis.ParseURL(redisURL)
	if err != nil {
		return fmt.Errorf("redis parse: %w", err)
	}
	rdb = redis.NewClient(opt)
	if err := rdb.Ping(ctx).Err(); err != nil {
		return fmt.Errorf("redis ping: %w", err)
	}
	return nil
}

func closeDB() {
	if pool != nil {
		pool.Close()
	}
	if rdb != nil {
		_ = rdb.Close()
	}
}

func runMigrate(ctx context.Context) error {
	if err := openDB(ctx); err != nil {
		return err
	}
	defer closeDB()
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := seedDefaults(ctx, false); err != nil {
		return fmt.Errorf("seed: %w", err)
	}
	if err := recomputeServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	return nil
}

func runReset(ctx context.Context) error {
	if err := openDB(ctx); err != nil {
		return err
	}
	defer closeDB()
	if _, err := pool.Exec(ctx, resetDropSQL); err != nil {
		return fmt.Errorf("drop: %w", err)
	}
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := seedDefaults(ctx, true); err != nil {
		return fmt.Errorf("seed: %w", err)
	}
	if err := recomputeServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	return nil
}

func envOr(k, d string) string {
	if v := os.GetenvEnvOr(k); v != "" {
		return v
	}
	return d
}

func hashPassword(password, salt string) string {
	h := sha256.Sum256([]byte(salt + ":" + password))
	return hex.EncodeToString(h[:])
}

func init() {
	_ = time.Now
	_ = strings.TrimSpace
}

