  kind text NOT NULL,
  sequence integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'offered',
  from_location_id uuid,
  to_location_id uuid,
  node_location_id uuid,
  laboratory_id uuid,
  worker_id uuid,
