import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

schemas = spec['components']['schemas']

def resolve(s):
    if '$ref' in s:
        name = s['$ref'].split('/')[-1]
        return schemas.get(name, {})
    return s

def shape(s, depth=0, seen=None):
    if seen is None:
        seen = set()
    s = resolve(s)
    t = s.get('type', 'object' if 'properties' in s else '')
    if t == 'object' or 'properties' in s:
        parts = []
        req = set(s.get('required', []))
        for k, v in s.get('properties', {}).items():
            r = '*' if k in req else ' '
            parts.append(f"{'  '*depth}{r}{k}: {shape(v, depth+1, seen)}")
        return "{\n" + "\n".join(parts) + f"\n{'  '*depth}}}"
    if t == 'array':
        return f"array<{shape(s.get('items', {}), depth, seen)}>"
    if 'enum' in s:
        return f"{t} enum={s['enum']}"
    fmt = s.get('format', '')
    return f"{t} {fmt}".strip()

out = open('/tmp/ops_compact.txt', 'w')
for path, methods in spec['paths'].items():
    for m, op in methods.items():
        if m not in ('get', 'post', 'put', 'patch', 'delete'):
            continue
        out.write("\n" + "=" * 78 + "\n")
        out.write(f"{m.upper()} {path} :: {op.get('operationId')}\n")
        if op.get('summary'):
            out.write(f"  # {op['summary']}\n")
        for p in op.get('parameters', []):
            out.write(f"  @param {p.get('in')}.{p.get('name')} (req={p.get('required')}): {shape(p.get('schema', {}))}\n")
        rb = op.get('requestBody', {})
        if rb:
            sch = rb.get('content', {}).get('application/json', {}).get('schema', {})
            out.write(f"  REQ {shape(sch)}\n")
        for code, resp in sorted(op.get('responses', {}).items()):
            sch = resp.get('content', {}).get('application/json', {}).get('schema', {})
            if sch:
                out.write(f"  RESP {code} {shape(sch)}\n")
            else:
                out.write(f"  RESP {code} (no json)\n")
out.close()
print("done")

