package main

import (
	"net/http"
	"strings"
)

func buildRouter() http.Handler {
	mux := http.NewServeMux()

	// public
	mux.HandleFunc("/ready", handleReady)
	mux.HandleFunc("/api/authenticate-user", handleAuthenticate)
	mux.HandleFunc("/api/ui/bootstrap", withAuth(handleBootstrap))

	// authenticated, role-checked via handlers (most do internal checks)
	mux.HandleFunc("/api/select-active-role", withAuth(handleSelectRole))
	mux.HandleFunc("/api/create-user", withAuth(handleCreateUser))
	mux.HandleFunc("/api/update-user-access", withAuth(handleUpdateUserAccess))
	mux.HandleFunc("/api/read-user/", withAuth(handleReadUser))
	mux.HandleFunc("/api/create-location", withAuth(handleCreateLocation))
	mux.HandleFunc("/api/update-location", withAuth(handleUpdateLocation))
	mux.HandleFunc("/api/set-location-status", withAuth(handleSetLocationStatus))
	mux.HandleFunc("/api/set-location-function-status", withAuth(handleSetLocationFunctionStatus))
	mux.HandleFunc("/api/create-connection", withAuth(handleCreateConnection))
	mux.HandleFunc("/api/set-connection-status", withAuth(handleSetConnectionStatus))
	mux.HandleFunc("/api/create-sample-type", withAuth(handleCreateSampleType))
	mux.HandleFunc("/api/update-sample-type", withAuth(handleUpdateSampleType))
	mux.HandleFunc("/api/configure-capacity", withAuth(handleConfigureCapacity))
	mux.HandleFunc("/api/configure-laboratory-acceptance", withAuth(handleConfigureLabAcceptance))
	mux.HandleFunc("/api/set-worker-availability", withAuth(handleSetWorkerAvailability))
	mux.HandleFunc("/api/check-serviceability", withAuth(handleCheckServiceability))
	mux.HandleFunc("/api/read-serviceability-snapshot", withAuth(handleReadServiceabilitySnapshot))
	mux.HandleFunc("/api/create-collection-request", withAuth(handleCreateCollectionRequest))
	mux.HandleFunc("/api/ingest-presealed-sample", withAuth(handleIngestPresealed))
	mux.HandleFunc("/api/read-sample-state/", withAuth(handleReadSampleState))
	mux.HandleFunc("/api/read-sample-lifecycle", withAuth(handleReadSampleLifecycle))
	mux.HandleFunc("/api/read-journey-plan", withAuth(handleReadJourneyPlan))
	mux.HandleFunc("/api/read-operations-state", withAuth(handleReadOperationsState))
	mux.HandleFunc("/api/list-role-work", withAuth(handleListRoleWork))
	mux.HandleFunc("/api/search-audit-trail", withAuth(handleSearchAudit))
	mux.HandleFunc("/api/accept-assignment", withAuth(handleAcceptAssignment))
	mux.HandleFunc("/api/decline-assignment", withAuth(handleDeclineAssignment))
	mux.HandleFunc("/api/collect-and-seal-sample", withAuth(handleCollectAndSeal))
	mux.HandleFunc("/api/initiate-handoff", withAuth(handleInitiateHandoff))
	mux.HandleFunc("/api/confirm-handoff", withAuth(handleConfirmHandoff))
	mux.HandleFunc("/api/confirm-laboratory-receipt", withAuth(handleConfirmLabReceipt))
	mux.HandleFunc("/api/record-laboratory-exception", withAuth(handleRecordLabException))
	mux.HandleFunc("/api/update-assignment-progress", withAuth(handleUpdateProgress))
	mux.HandleFunc("/api/record-worker-location", withAuth(handleRecordWorkerLocation))
	mux.HandleFunc("/api/record-handling-checkpoint", withAuth(handleHandlingCheckpoint))
	mux.HandleFunc("/api/cancel-journey", withAuth(handleCancelJourney))
	mux.HandleFunc("/api/split-journey", withAuth(handleSplitJourney))
	mux.HandleFunc("/api/merge-journeys", withAuth(handleMergeJourneys))
	mux.HandleFunc("/api/reroute-journey", withAuth(handleRerouteJourney))
	mux.HandleFunc("/api/edit-active-plan", withAuth(handleEditActivePlan))
	mux.HandleFunc("/api/report-disruption", withAuth(handleReportDisruption))
	mux.HandleFunc("/api/events", withAuth(handleEvents))

	// static frontend + map assets
	registerStatic(mux)

	return methodGuard(logging(mux))
}

func withAuth(h http.HandlerFunc) http.Handler {
	return requireAuth(h)
}

func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		next.ServeHTTP(w, r)
	})
}

// methodGuard restricts POST endpoints that are not GET/WS to POST only.
func methodGuard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		if strings.HasPrefix(path, "/api/") {
			switch path {
			case "/api/ui/bootstrap", "/api/read-serviceability-snapshot", "/api/read-sample-state/", "/api/read-user/", "/api/events", "/ready":
				// allowed methods handled per handler
			default:
				if r.Method != http.MethodPost {
					errResp(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
					return
				}
			}
		}
		next.ServeHTTP(w, r)
	})
}

