func handleReadUser(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	userID := strings.TrimPrefix(r.URL.Path, "/api/read-user/")
	if userID == "" {
		errResp(w, http.StatusNotFound, "not_found", "userId required")
		return
	}
	// admin or self
	if ru.ActiveRole != "administrator" && ru.UserID != userID {
		errResp(w, http.StatusForbidden, "forbidden", "not permitted")
		return
	}
	var username, email, fullName, phone string
	var roles, quals []string
	var active bool
	var assignedLoc *string
	err := pool.QueryRow(r.Context(),
		`SELECT username, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''), roles, qualifications, active, assigned_location_id FROM users WHERE user_id=$1`, userID).
		Scan(&username, &email, &fullName, &phone, &roles, &quals, &active, &assignedLoc)
	if err != nil {
		errResp(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	certs := loadCertifications(r.Context(), userID)
	data := map[string]interface{}{
		"userId":         userID,
		"username":       username,
		"roles":          roles,
		"qualifications": quals,
		"certifications": certs,
		"active":         active,
	}
	if email != "" {
		data["email"] = email
	}
	if fullName != "" {
		data["fullName"] = fullName
	}
	if phone != "" {
		data["phone"] = phone
	}
	if assignedLoc != nil {
		data["assignedLocationId"] = *assignedLoc
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": data})
}

func loadCertifications(ctx context.Context, userID string) []map[string]interface{} {
	rows, err := pool.Query(ctx, `SELECT code, active, COALESCE(expires_at::text,'') FROM certifications WHERE user_id=$1`, userID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var code, exp string
		var active bool
		_ = rows.Scan(&code, &active, &exp)
		m := map[string]interface{}{"code": code, "active": active}
		if exp != "" {
			m["expiresAt"] = exp
		}
		out = append(out, m)
	}
	return out
}

