package main

import (
	"context"
	"fmt"
)

const seedQualificationAmber = "collect-amber"
const seedQualificationIndigo = "collect-indigo"
const seedQualificationFrost = "collect-frost"
const seedQualificationPulse = "collect-pulse"

// seedDefaults inserts default sample types and, when fullNetwork is true, a
// default Bangalore network with collection points, hubs, a laboratory and the
// connections between them.
func seedDefaults(ctx context.Context, fullNetwork bool) error {
	if err := seedSampleTypes(ctx); err != nil {
		return err
	}
	if !fullNetwork {
		return nil
	}
	return seedNetwork(ctx)
}

func seedSampleTypes(ctx context.Context) error {
	types := []struct {
		name              string
		reqQual           string
		container         string
		tMin, tMax        float64
		incompatible       []string
		cooled            bool
		batching          bool
	}{
		{"Amber", seedQualificationAmber, "box", -5, 30, nil, false, true},
		{"Indigo", seedQualificationIndigo, "box", -5, 30, []string{"Amber"}, false, true},
		{"Frost", seedQualificationFrost, "cooler", -25, 2, nil, true, true},
		{"Pulse", seedQualificationPulse, "box", -5, 30, nil, false, false},
	}
	for _, t := range types {
		var existing string
		err := pool.QueryRow(ctx, `SELECT sample_type_id FROM sample_types WHERE name=$1`, t.name).Scan(&existing)
		if err == nil {
			_, err := pool.Exec(ctx, `UPDATE sample_types SET qualified_collector_required=true, required_qualification=$1, container_type=$2, temperature_min_c=$3, temperature_max_c=$4, incompatible_sample_types=$5, requires_cooled_route=$6, batching_allowed=$7, active=true WHERE name=$8`,
				t.reqQual, t.container, t.tMin, t.tMax, arrayOrNull(t.incompatible), t.cooled, t.batching, t.name)
			if err != nil {
				return fmt.Errorf("update sample type %s: %w", t.name, err)
			}
			continue
		}
		_, err = pool.Exec(ctx, `INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
			VALUES ($1,true,$2,$3,$4,$5,$6,$7,$8)`,
			t.name, t.reqQual, t.container, t.tMin, t.tMax, arrayOrNull(t.incompatible), t.cooled, t.batching)
		if err != nil {
			return fmt.Errorf("insert sample type %s: %w", t.name, err)
		}
	}
	return nil
}

func arrayOrNull(s []string) interface{} {
	if len(s) == 0 {
		return []string{}
	}
	return s
}

type seedLoc struct {
	name        string
	lat, lng    float64
	coverageKm  float64
	handlingMin int
	coll, transf, hub, lab bool
	cap, cooled int
}

func seedNetwork(ctx context.Context) error {
	locs := []seedLoc{
		{"Bangalore Collection Centre North", 12.99, 77.58, 5, 10, true, false, false, false, 20, 5},
		{"Bangalore Collection Centre South", 12.92, 77.58, 5, 10, true, true, false, false, 20, 5},
		{"Bangalore Hub Central", 12.9716, 77.5946, 0, 15, true, true, true, false, 50, 10},
		{"Bangalore Laboratory", 12.95, 77.61, 0, 10, true, false, false, true, 100, 30},
	}
	ids := map[string]string{}
	for _, l := range locs {
		var id string
		err := pool.QueryRow(ctx, `SELECT location_id FROM locations WHERE name=$1`, l.name).Scan(&id)
		if err != nil {
			err = pool.QueryRow(ctx, `INSERT INTO locations (name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory)
				VALUES ($1,$2,$3,$4,$5,true,$6,$7,$8,$9) RETURNING location_id`,
				l.name, l.lat, l.lng, l.coverageKm, l.handlingMin, l.coll, l.transf, l.hub, l.lab).Scan(&id)
			if err != nil {
				return fmt.Errorf("seed location %s: %w", l.name, err)
			}
		}
		ids[l.name] = id
		// capacity pool
		_, _ = pool.Exec(ctx, `INSERT INTO capacity_pools (resource_id, resource_kind, capacity_units, cooled_capacity_units)
			VALUES ($1,'location',$2,$3) ON CONFLICT (resource_id) DO UPDATE SET capacity_units=$2, cooled_capacity_units=$3`,
			id, l.cap, l.cooled)
	}
	// connections
	conns := []struct {
		from, to string
		min      int
		cost     float64
		cooled   bool
	}{
		{"Bangalore Collection Centre North", "Bangalore Hub Central", 25, 10, true},
		{"Bangalore Collection Centre South", "Bangalore Hub Central", 25, 10, true},
		{"Bangalore Hub Central", "Bangalore Laboratory", 30, 15, true},
		{"Bangalore Collection Centre North", "Bangalore Laboratory", 55, 25, true},
		{"Bangalore Collection Centre South", "Bangalore Laboratory", 50, 22, true},
	}
	for _, c := range conns {
		from, to := ids[c.from], ids[c.to]
		var existing string
		err := pool.QueryRow(ctx, `SELECT connection_id FROM connections WHERE from_location_id=$1 AND to_location_id=$2`, from, to).Scan(&existing)
		if err == nil {
			_, _ = pool.Exec(ctx, `UPDATE connections SET travel_minutes=$1, cost_units=$2, cooled=$3, active=true WHERE connection_id=$4`, c.min, c.cost, c.cooled, existing)
			continue
		}
		_, err = pool.Exec(ctx, `INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active) VALUES ($1,$2,$3,$4,$5,true)`,
			from, to, c.min, c.cost, c.cooled)
		if err != nil {
			return fmt.Errorf("seed connection %s->%s: %w", c.from, c.to, err)
		}
	}
	// laboratory acceptance: lab accepts all default sample types
	labID := ids["Bangalore Laboratory"]
	rows, err := pool.Query(ctx, `SELECT sample_type_id FROM sample_types WHERE name IN ('Amber','Indigo','Frost','Pulse')`)
	if err != nil {
		return err
	}
	defer rows.Close()
	var typeIDs []string
	for rows.Next() {
		var sid string
		if err := rows.Scan(&sid); err != nil {
			return err
		}
		typeIDs = append(typeIDs, sid)
	}
	for _, sid := range typeIDs {
		_, _ = pool.Exec(ctx, `INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts) VALUES ($1,$2,true) ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=true`,
			labID, sid)
	}
	return nil
