package main

import (
	"context"
	"crypto/rand"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"
)

func newUUID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func ensureInitialAdmin(ctx context.Context) error {
	var count int
	if err := pool.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	salt := newToken()
	pwHash := salt + ":" + hashPassword(password, salt)
	_, err := pool.Exec(ctx, `INSERT INTO users (username, password_hash, roles, active) VALUES ($1,$2,$3,true) ON CONFLICT (username) DO NOTHING`,
		username, pwHash, []string{"administrator"})
	if err != nil {
		return err
	}
	return nil
}

func handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.Username == "" || body.Password == "" {
		errResp(w, http.StatusUnauthorized, "invalid_credentials", "username and password required")
		return
	}
	var userID, passwordHash, activeRole string
	var roles []string
	var active bool
	err := pool.QueryRow(r.Context(),
		`SELECT user_id, password_hash, roles, active FROM users WHERE username=$1`, body.Username).
		Scan(&userID, &passwordHash, &roles, &active)
	if err != nil || !active {
		errResp(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		return
	}
	// stored hash format: salt:hash, reconstructed at write time. We stored only hash; verify using stored salt prefix.
	// To keep simple, we store password_hash as "salt:hash".
	salt := strings.SplitN(passwordHash, ":", 2)[0]
	if hashPassword(body.Password, salt) != passwordHash {
		errResp(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		return
	}
	// pick active role = first role
	if len(roles) > 0 {
		activeRole = roles[0]
	}
	token, err := createSession(r.Context(), userID, activeRole)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	audit(r.Context(), userID, activeRole, "sign_in", "user", userID, true, map[string]interface{}{"username": body.Username})
	jsonResp(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"sessionToken": token,
			"userId":        userID,
			"roles":         roles,
			"activeRole":    activeRole,
		},
	})
}

func handleSelectRole(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Role string `json:"role"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	ru := current(r)
	if !contains(ru.Roles, body.Role) {
		errResp(w, http.StatusForbidden, "role_not_held", "role not held by user")
		return
	}
	token := bearerToken(r)
	_, err := pool.Exec(r.Context(), `UPDATE sessions SET active_role=$1 WHERE token=$2`, body.Role, token)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	audit(r.Context(), ru.UserID, body.Role, "select_role", "user", ru.UserID, true, nil)
	jsonResp(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"activeRole": body.Role,
			"roles":      ru.Roles,
		},
	})
}

func handleBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		errResp(w, http.StatusMethodNotAllowed, "method_not_allowed", "GET required")
		return
	}
	ru := current(r)
	roleSelectionRequired := ru.ActiveRole == ""
	var fullName interface{}
	if fn := getUserField(r.Context(), ru.UserID, "full_name"); fn != "" {
		fullName = fn
	}
	serverTime := now().Format(time.RFC3339)
	data := map[string]interface{}{
		"user": map[string]interface{}{
			"userId":                ru.UserID,
			"username":              ru.Username,
			"fullName":              fullName,
			"roles":                 ru.Roles,
			"activeRole":            ru.ActiveRole,
			"roleSelectionRequired": roleSelectionRequired,
		},
		"serverTime": serverTime,
	}
	// requesterSamples (role-specific) handled by frontend via list-role-work
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": data})
}

