	if roles == nil {
		roles = []string{}
	}
	quals := body.Qualifications
	if quals == nil {
		quals = []string{}
	}
	var assignedLoc interface{}
	if body.AssignedLocationID != "" {
		assignedLoc = body.AssignedLocationID
	}
	_, err := pool.Exec(r.Context(), `UPDATE users SET roles=$1, qualifications=$2, active=$3, assigned_location_id=$4 WHERE user_id=$5`,
		roles, quals, body.Active, assignedLoc, body.UserID)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	certs := saveCertifications(r.Context(), body.UserID, body.Certifications)
