package main

import (
	"context"
	"strconv"
)

type coord struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type funcStates struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

func parseFunctions(list []string) funcStates {
	var f funcStates
	for _, fn := range list {
		switch fn {
		case "collection_point":
			f.CollectionPoint = true
		case "transfer_point":
			f.TransferPoint = true
		case "hub":
			f.Hub = true
		case "laboratory":
			f.Laboratory = true
		}
	}
	return f
}

func functionsToList(f funcStates) []string {
	var out []string
	if f.CollectionPoint {
		out = append(out, "collection_point")
	}
	if f.TransferPoint {
		out = append(out, "transfer_point")
	}
	if f.Hub {
		out = append(out, "hub")
	}
	if f.Laboratory {
		out = append(out, "laboratory")
	}
	return out
}

func locationResponse(ctx context.Context, id string) map[string]interface{} {
	var name string
	var lat, lng, cov float64
	var handling int
