)

func adminOnly(ru *requestUser) bool { return ru.ActiveRole == "administrator" }

func handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if !adminOnly(ru) {
		errResp(w, http.StatusForbidden, "forbidden", "administrator only")
		return
	}
	var body struct {
		Name            string  `json:"name"`
		Coordinate      *coord  `json:"coordinate"`
		CoverageKm      *float64 `json:"coverageKm"`
		HandlingMinutes *int    `json:"handlingMinutes"`
		Active          bool    `json:"active"`
		Functions       []string `json:"functions"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.Name == "" || body.Coordinate == nil {
		errResp(w, http.StatusBadRequest, "invalid_coordinate", "name and coordinate required")
		return
	}
	lat, lng := body.Coordinate.Latitude, body.Coordinate.Longitude
	if lat < -90 || lat > 90 || lng < -180 || lng > 180 {
		errResp(w, http.StatusBadRequest, "invalid_coordinate", "coordinate out of range")
		return
	}
	cov := 0.0
	if body.CoverageKm != nil {
		cov = *body.CoverageKm
	}
	if cov < 0 {
		errResp(w, http.StatusBadRequest, "invalid_node_coverage", "coverage must be >= 0")
		return
	}
	handling := 0
	if body.HandlingMinutes != nil {
		handling = *body.HandlingMinutes
	}
