package main

import (
	"context"
	"encoding/json"
	"math"
	"sync/atomic"
	"time"
)

var netRevision int64 = 1

func bumpNetworkRevision() {
	atomic.AddInt64(&netRevision, 1)
}

func recomputeServiceabilityAsync(ctx context.Context) {
	bumpNetworkRevision()
	go func() {
		_ = recomputeServiceability(context.Background())
	}()
}

type locationNode struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	CollectionPoint bool
	TransferPoint   bool
	Hub             bool
	Laboratory      bool
}

type connectionEdge struct {
	ID            string
	From, To      string
	TravelMinutes int
	Cost          float64
	Cooled        bool
	Active        bool
}

func loadNetwork(ctx context.Context) (map[string]*locationNode, []*connectionEdge, error) {
	nodes := map[string]*locationNode{}
	rows, err := pool.Query(ctx, `SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations`)
	if err != nil {
		return nil, nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var n locationNode
		if err := rows.Scan(&n.ID, &n.Name, &n.Lat, &n.Lng, &n.CoverageKm, &n.HandlingMinutes, &n.Active, &n.CollectionPoint, &n.TransferPoint, &n.Hub, &n.Laboratory); err != nil {
			return nil, nil, err
		}
		nodes[n.ID] = &n
	}
	conns := []*connectionEdge{}
	rows2, err := pool.Query(ctx, `SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if err != nil {
		return nil, nil, err
	}
	defer rows2.Close()
	for rows2.Next() {
		var c connectionEdge
		if err := rows2.Scan(&c.ID, &c.From, &c.To, &c.TravelMinutes, &c.Cost, &c.Cooled, &c.Active); err != nil {
			return nil, nil, err
		}
		conns = append(conns, &c)
	}
	return nodes, conns, nil
}

func loadLabAcceptance(ctx context.Context) (map[string]map[string]bool, error) {
	rows, err := pool.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	m := map[string]map[string]bool{}
	for rows.Next() {
		var lab, st string
		var acc bool
		if err := rows.Scan(&lab, &st, &acc); err != nil {
			return nil, err
		}
		if m[lab] == nil {
			m[lab] = map[string]bool{}
		}
		m[lab][st] = acc
	}
	return m, nil
}

func loadCapacity(ctx context.Context) (map[string]map[string]int, error) {
	// returns resource_id -> {"regular_config","cooled_config","regular_reserved","cooled_reserved"}
	rows, err := pool.Query(ctx, `SELECT resource_id, capacity_units, cooled_capacity_units FROM capacity_pools`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	m := map[string]map[string]int{}
	for rows.Next() {
		var rid string
		var reg, cooled int
		if err := rows.Scan(&rid, &reg, &cooled); err != nil {
			return nil, err
		}
		m[rid] = map[string]int{"reg_config": reg, "cooled_config": cooled, "reg_reserved": 0, "cooled_reserved": 0}
	}
	rows2, err := pool.Query(ctx, `SELECT resource_id, units, cooled FROM capacity_reservations`)
	if err != nil {
		return m, nil
	}
	defer rows2.Close()
	for rows2.Next() {
		var rid string
		var units int
		var cooled bool
		if err := rows2.Scan(&rid, &units, &cooled); err != nil {
			continue
		}
		if m[rid] == nil {
			m[rid] = map[string]int{"reg_config": 0, "cooled_config": 0, "reg_reserved": 0, "cooled_reserved": 0}
		}
		if cooled {
