}

func recomputeServiceability(ctx context.Context) error {
	nodes, _, err := loadNetwork(ctx)
	if err != nil {
		return err
	}
	regions := []map[string]interface{}{}
	count := 0
	for _, n := range nodes {
		if n.Active && n.CollectionPoint {
			count++
			regions = append(regions, map[string]interface{}{
