func checkServiceabilityLogic(ctx context.Context, originLat, originLng float64, originType string, originNodeID string, sampleTypeID string, requiresCooled bool, deadline time.Time) servResult {
	version := latestServVersion(ctx)
	res := servResult{ServiceabilityVersion: version}
	nodes, edges, err := loadNetwork(ctx)
	if err != nil {
		res.Reason = "no_route"
		return res
	}
	accepts, _ := loadLabAcceptance(ctx)
	caps, _ := loadCapacity(ctx)

	var candidates []*locationNode
	if originType == "node" && originNodeID != "" {
		n := nodes[originNodeID]
		if n == nil || !n.Active || !n.CollectionPoint {
			res.Reason = "outside_service_coverage"
			return res
		}
		candidates = []*locationNode{n}
	} else {
		candidates = servingCollectionNodes(nodes, originLat, originLng)
	}
	if len(candidates) == 0 {
		res.Reason = "outside_service_coverage"
		return res
	}

	// check accepting lab exists
	labExists := false
	for _, n := range nodes {
		if n.Laboratory && n.Active && accepts[n.ID] != nil && accepts[n.ID][sampleTypeID] {
			labExists = true
			break
		}
	}
	if !labExists {
		res.Reason = "no_accepting_laboratory"
		return res
	}

	var bestPath *routePath
	var failReason string
	for _, start := range candidates {
		p, reason := findRoute(ctx, nodes, edges, accepts, caps, sampleTypeID, requiresCooled, start.ID, deadline)
		if p != nil {
			if bestPath == nil || p.TotalTime < bestPath.TotalTime {
				bestPath = p
			}
		} else if reason != "" {
			failReason = reason
		}
	}
	if bestPath == nil {
		if failReason == "" {
			failReason = "no_route"
		}
		// distinguish capacity vs route vs handling
		// check capacity availability generally
		if !hasAnyCapacity(ctx, requiresCooled) {
			res.Reason = "insufficient_capacity"
			return res
		}
		if requiresCooled && !hasCooledRoute(edges) {
			res.Reason = "handling_rules_unsatisfiable"
			return res
		}
		res.Reason = failReason
		return res
	}
	arrival := now().Add(time.Duration(bestPath.TotalTime) * time.Minute)
	if !deadline.IsZero() && arrival.After(deadline) {
		res.Reason = "deadline_unreachable"
		return res
	}
	// target lab = last node
	targetLab := bestPath.Nodes[len(bestPath.Nodes)-1].ID
	res.Serviceable = true
	res.Reason = "serviceable"
	res.TargetLaboratoryID = targetLab
	res.EstimatedArrivalAt = arrival
	return res
}

func hasAnyCapacity(ctx context.Context, cooled bool) bool {
	caps, _ := loadCapacity(ctx)
	for _, c := range caps {
		if availableCapacity(c, cooled) >= 1 {
			return true
		}
	}
	return false
}

func hasCooledRoute(edges []*connectionEdge) bool {
	for _, e := range edges {
		if e.Active && e.Cooled {
			return true
		}
	}
	return false
}

func latestServVersion(ctx context.Context) int {
	var v int
	_ = pool.QueryRow(ctx, `SELECT version FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).Scan(&v)
	if v == 0 {
		v = 1
	}
	return v
}

func recomputeServiceability(ctx context.Context) error {
	nodes, _, err := loadNetwork(ctx)
	if err != nil {
		return err
	}
	regions := []map[string]interface{}{}
	count := 0
	for _, n := range nodes {
		if n.Active && n.CollectionPoint {
			count++
			regions = append(regions, map[string]interface{}{
				"locationId":  n.ID,
				"name":         n.Name,
				"latitude":     n.Lat,
				"longitude":    n.Lng,
				"coverageKm":   n.CoverageKm,
			})
		}
	}
	regionsJSON, _ := json.Marshal(regions)
	rev := int(atomic.LoadInt64(&netRevision))
	_, err = pool.Exec(ctx, `INSERT INTO serviceability_versions (version, status, network_revision, computed_at, regions, active_collection_point_count)
		VALUES ((SELECT COALESCE(MAX(version),0)+1 FROM serviceability_versions), 'complete', $1, now(), $2::jsonb, $3)`,
		rev, string(regionsJSON), count)
	if err != nil {
		return err
	}
	return nil
}

func handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		errResp(w, http.StatusMethodNotAllowed, "method_not_allowed", "GET required")
		return
	}
	var version, rev, count int
	var status, computedAt string
	var regionsJSON []byte
	err := pool.QueryRow(r.Context(), `SELECT version, status, network_revision, computed_at::text, regions, active_collection_point_count FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).
		Scan(&version, &status, &rev, &computedAt, &regionsJSON, &count)
	if err != nil {
		// compute one synchronously
		_ = recomputeServiceability(r.Context())
		err = pool.QueryRow(r.Context(), `SELECT version, status, network_revision, computed_at::text, regions, active_collection_point_count FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).
			Scan(&version, &status, &rev, &computedAt, &regionsJSON, &count)
		if err != nil {
			errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	var regions []interface{}
	_ = json.Unmarshal(regionsJSON, &regions)
	if regions == nil {
		regions = []interface{}{}
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"version":                     version,
		"status":                      status,
		"computedAt":                  computedAt,
		"networkRevision":             rev,
		"regions":                     regions,
		"activeCollectionPointCount":  count,
	}})
}", "path": "/workspace/backend/serviceability.go"}

