package main

import (
	"net/http"
	"time"
)

func handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "requester" && ru.ActiveRole != "administrator" && ru.ActiveRole != "dispatcher" {
		errResp(w, http.StatusForbidden, "forbidden", "requester role required")
		return
	}
	var body struct {
		Origin              *coord  `json:"origin"`
		OriginType          string  `json:"originType"`
		OriginNodeID        string  `json:"originNodeId"`
		SampleTypeID        string  `json:"sampleTypeId"`
		RequestedAt         string  `json:"requestedAt"`
		DeliveryDeadline    string  `json:"deliveryDeadline"`
		EarliestCollectionAt string `json:"earliestCollectionAt"`
		LatestCollectionAt  string  `json:"latestCollectionAt"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.SampleTypeID == "" {
		errResp(w, http.StatusBadRequest, "invalid_json", "sampleTypeId required")
		return
	}
	if body.OriginType == "node" {
		if body.OriginNodeID == "" {
			errResp(w, http.StatusBadRequest, "invalid_origin", "originNodeId required for node origin")
			return
		}
	} else {
		if body.Origin == nil {
			errResp(w, http.StatusBadRequest, "invalid_origin", "origin coordinates required")
			return
		}
		if body.OriginType != "home" && body.OriginType != "clinic" {
			errResp(w, http.StatusBadRequest, "invalid_origin_type", "originType must be home/clinic/node")
			return
		}
	}
	deadline, err := parseRFC3339(body.DeliveryDeadline)
	if err != nil {
		errResp(w, http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline")
		return
	}
	if !body.EarliestCollectionAt.IsZero() || !body.LatestCollectionAt.IsZero() {
		ec, _ := parseRFC3339(body.EarliestCollectionAt)
		lc, _ := parseRFC3339(body.LatestCollectionAt)
		if !ec.IsZero() && !lc.IsZero() && ec.After(lc) {
			errResp(w, http.StatusBadRequest, "invalid_collection_window", "earliest after latest")
			return
		}
	}
	// load sample type
	var requiresCooled bool
	err = pool.QueryRow(r.Context(), `SELECT requires_cooled_route FROM sample_types WHERE sample_type_id=$1`, body.SampleTypeID).Scan(&requiresCooled)
	if err != nil {
		errResp(w, http.StatusNotFound, "not_found", "sample type not found")
		return
	}
	lat, lng := 0.0, 0.0
	if body.Origin != nil {
		lat, lng = body.Origin.Latitude, body.Origin.Longitude
	}
	res := checkServiceabilityLogic(r.Context(), lat, lng, body.OriginType, body.OriginNodeID, body.SampleTypeID, requiresCooled, deadline)
	data := map[string]interface{}{
		"serviceable":            res.Serviceable,
		"reason":                  res.Reason,
		"serviceabilityVersion":   res.ServiceabilityVersion,
	}
	if res.TargetLaboratoryID != "" {
		data["targetLaboratoryId"] = res.TargetLaboratoryID
	}
	if !res.EstimatedArrivalAt.IsZero() {
		data["estimatedArrivalAt"] = res.EstimatedArrivalAt.Format(time.RFC3339)
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "check_serviceability", "sample_type", body.SampleTypeID, true, map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason})
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": data})
}

