package main

import (
	"context"
	"encoding/json"
)

// checkIdempotency returns a cached response body and status code if the key was seen.
func checkIdempotency(ctx context.Context, key, userID string) (interface{}, int) {
	if key == "" {
		return nil, 0
	}
	cctx := ctx
	if cctx == nil {
		cctx = context.Background()
	}
	var bodyJSON []byte
	var code int
	err := pool.QueryRow(cctx, `SELECT response_body, status_code FROM idempotency_keys WHERE key=$1`, key).Scan(&bodyJSON, &code)
	if err != nil {
		return nil, 0
	}
	var body interface{}
	if err := json.Unmarshal(bodyJSON, &body); err != nil {
		return nil, 0
	}
	return body, code
}

func storeIdempotency(ctx context.Context, key, userID string, status int, body interface{}) {
	if key == "" {
		return
	}
	cctx := ctx
	if cctx == nil {
		cctx = context.Background()
	}
	bj, err := json.Marshal(body)
	if err != nil {
		return
	}
	_, _ = pool.Exec(cctx, `INSERT INTO idempotency_keys (key, user_id, endpoint, response_body, status_code) VALUES ($1,$2,'',$3,$4::jsonb) ON CONFLICT (key) DO NOTHING`,
		key, nilUUID(userID), status, string(bj))
}

