package main

import (
	"net/http"
)

func handleIngestPresealed(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	allowed := map[string]bool{"collection_professional": true, "delivery_partner": true, "node_handler": true, "laboratory_team": true, "administrator": true}
	if !allowed[ru.ActiveRole] {
		errResp(w, http.StatusForbidden, "forbidden", "not permitted")
		return
	}
	var body struct {
		OriginType            string   `json:"originType"`
		OriginNodeID          string   `json:"originNodeId"`
		DeliveryDeadline      string   `json:"deliveryDeadline"`
		SampleTypeID          string   `json:"sampleTypeId"`
		ContainerType         string   `json:"containerType"`
		TemperatureMinC      float64  `json:"temperatureMinC"`
		TemperatureMaxC      float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string `json:"incompatibleSampleTypes"`
		IdempotencyKey        string   `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	if body.OriginType != "clinic" && body.OriginType != "node" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_origin_type", "presealed origin must be clinic or node")
		return
	}
	if body.OriginNodeID == "" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_origin", "originNodeId required")
		return
	}
	deadline, err := parseRFC3339(body.DeliveryDeadline)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline")
		return
	}
	var stContainer string
	var stMin, stMax float64
	var requiresCooled, batching bool
	var incompat []string
	err = pool.QueryRow(r.Context(), `SELECT container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types WHERE sample_type_id=$1`, body.SampleTypeID).
		Scan(&stContainer, &stMin, &stMax, &incompat, &requiresCooled, &batching)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "sample type not found")
		return
	}
	container := body.ContainerType
	if container == "" {
		container = stContainer
	}
	tMin, tMax := body.TemperatureMinC, body.TemperatureMaxC
	if tMin == 0 && tMax == 0 {
		tMin, tMax = stMin, stMax
	}
	incompatible := body.IncompatibleSampleTypes
	if incompatible == nil {
		incompatible = incompat
	}
	if incompatible == nil {
		incompatible = []string{}
	}
	// origin node coordinates
	var lat, lng float64
	err = pool.QueryRow(r.Context(), `SELECT latitude, longitude FROM locations WHERE location_id=$1`, body.OriginNodeID).Scan(&lat, &lng)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_origin", "origin node not found")
		return
	}
	requestID := newUUID()
	sampleID := newUUID()
	_, err = pool.Exec(r.Context(), `INSERT INTO requests (request_id, requester_id, sample_id, origin_type, origin_location_id, origin_lat, origin_lng, requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, already_sealed, serviceable, serviceability_reason)
		VALUES ($1,$2,$3,$4,$5,$6,$7,now(),$8,$9,$10,$11,$12,$13,true,true,'serviceable')`,
		requestID, ru.UserID, sampleID, body.OriginType, body.OriginNodeID, lat, lng, deadline, body.SampleTypeID, container, tMin, tMax, incompatible)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, err = pool.Exec(r.Context(), `INSERT INTO samples (sample_id, request_id, requester_id, sample_type_id, status, sealed, current_holder_id, origin_type, origin_lat, origin_lng, latest_lat, latest_lng, location_recorded_at, delivery_deadline, container_type, temperature_min_c, temperature_max_c)
		VALUES ($1,$2,$3,$4,'sealed',true,$5,$6,$7,$8,$7,$8,now(),$9,$10,$11,$12)`,
		sampleID, requestID, ru.UserID, body.SampleTypeID, ru.UserID, body.OriginType, lat, lng, deadline, container, tMin, tMax)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	pr, failReason := planJourney(r.Context(), planInput{
		originLat: lat, originLng: lng, originType: "node", originNodeID: body.OriginNodeID,
		sampleTypeID: body.SampleTypeID, requiresCooled: requiresCooled, batchingAllowed: batching,
		deadline: deadline, alreadySealed: true,
	})
	data := map[string]interface{}{
		"requestId":            requestID,
		"sampleId":              sampleID,
		"serviceability":        "serviceable",
		"activeAssignmentIds":  []string{},
		"alreadySealed":        true,
		"originType":           body.OriginType,
	}
	if pr == nil {
		_, _ = pool.Exec(r.Context(), `UPDATE requests SET serviceable=false, serviceability_reason=$2 WHERE request_id=$1`, requestID, failReason)
		data["serviceability"] = "unserviceable"
		data["serviceabilityReason"] = failReason
	} else {
		_, _ = pool.Exec(r.Context(), `UPDATE requests SET target_laboratory_id=$2 WHERE request_id=$1`, requestID, pr.targetLabID)
		_, _ = pool.Exec(r.Context(), `UPDATE journeys SET sample_id=$2 WHERE journey_id=$1`, pr.journeyID, sampleID)
		_, _ = pool.Exec(r.Context(), `UPDATE assignments SET sample_id=$2 WHERE journey_id=$1`, pr.journeyID, sampleID)
		_, _ = pool.Exec(r.Context(), `UPDATE capacity_reservations SET sample_id=$2 WHERE journey_id=$1`, pr.journeyID, sampleID)
		data["journeyId"] = pr.journeyID
		data["targetLaboratoryId"] = pr.targetLabID
		data["activeAssignmentIds"] = pr.assignmentIDs
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "ingest_presealed", "sample", sampleID, true, map[string]interface{}{"requestId": requestID})
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "administrator" && ru.ActiveRole != "node_handler" && ru.ActiveRole != "laboratory_team" {
		errResp(w, http.StatusForbidden, "forbidden", "not permitted")
		return
	}
	var body struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits int    `json:"cooledCapacityUnits"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.ResourceID == "" || body.CapacityUnits < 0 || body.CooledCapacityUnits < 0 {
		errResp(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
		return
	}
	// check reserved not exceeded
	var regRes, cooledRes int
	_ = pool.QueryRow(r.Context(), `SELECT COALESCE(SUM(units) FILTER (WHERE cooled=false),0), COALESCE(SUM(units) FILTER (WHERE cooled=true),0) FROM capacity_reservations WHERE resource_id=$1`, body.ResourceID).Scan(&regRes, &cooledRes)
	if body.CapacityUnits < regRes || body.CooledCapacityUnits < cooledRes {
		errResp(w, http.StatusConflict, "capacity_reserved", "cannot reduce below reserved")
		return
	}
	_, err := pool.Exec(r.Context(), `INSERT INTO capacity_pools (resource_id, resource_kind, capacity_units, cooled_capacity_units) VALUES ($1,'location',$2,$3) ON CONFLICT (resource_id) DO UPDATE SET capacity_units=$2, cooled_capacity_units=$3`,
		body.ResourceID, body.CapacityUnits, body.CooledCapacityUnits)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "configure_capacity", "capacity", body.ResourceID, true, map[string]interface{}{"units": body.CapacityUnits, "cooled": body.CooledCapacityUnits})
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"resourceId":          body.ResourceID,
		"capacityUnits":       body.CapacityUnits,
		"cooledCapacityUnits": body.CooledCapacityUnits,
	}})
}

func handleConfigureLabAcceptance(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "administrator" && ru.ActiveRole != "laboratory_team" {
		errResp(w, http.StatusForbidden, "forbidden", "not permitted")
		return
	}
	var body struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.LaboratoryID == "" || body.SampleTypeID == "" {
		errResp(w, http.StatusBadRequest, "invalid_acceptance", "laboratoryId and sampleTypeId required")
		return
	}
	var accID string
	err := pool.QueryRow(r.Context(), `INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts) VALUES ($1,$2,$3) ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$3 RETURNING acceptance_id`,
		body.LaboratoryID, body.SampleTypeID, body.Accepts).Scan(&accID)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	recomputeServiceabilityAsync(r.Context())
	audit(r.Context(), ru.UserID, ru.ActiveRole, "configure_lab_acceptance", "laboratory", body.LaboratoryID, true, map[string]interface{}{"accepts": body.Accepts})
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{"acceptanceId": accID, "accepts": body.Accepts}})
}

func handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "administrator" && ru.ActiveRole != "dispatcher" {
		errResp(w, http.StatusForbidden, "forbidden", "not permitted")
		return
	}
	var body struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.WorkerID == "" || body.CapacityUnits < 0 {
		errResp(w, http.StatusBadRequest, "invalid_capacity", "invalid")
		return
	}
	ct, err := pool.Exec(r.Context(), `UPDATE users SET available=$1, capacity_units=$2 WHERE user_id=$3`, body.Available, body.CapacityUnits, body.WorkerID)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if ct.RowsAffected() == 0 {
		errResp(w, http.StatusNotFound, "not_found", "worker not found")
		return
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "set_worker_availability", "worker", body.WorkerID, true, map[string]interface{}{"available": body.Available, "capacity": body.CapacityUnits})
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"workerId":       body.WorkerID,
		"available":       body.Available,
		"capacityUnits":  body.CapacityUnits,
	}})
}

