	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": connectionResponse(r.Context(), id)})
}

func handleSetConnectionStatus(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if !adminOnly(ru) {
		errResp(w, http.StatusForbidden, "forbidden", "administrator only")
		return
	}
	var body struct {
		ConnectionID string `json:"connectionId"`
		Active       bool   `json:"active"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	ct, err := pool.Exec(r.Context(), `UPDATE connections SET active=$1 WHERE connection_id=$2`, body.Active, body.ConnectionID)
	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if ct.RowsAffected() == 0 {
		errResp(w, http.StatusNotFound, "not_found", "connection not found")
		return
	}
	recomputeServiceabilityAsync(r.Context())
	audit(r.Context(), ru.UserID, ru.ActiveRole, "set_connection_status", "connection", body.ConnectionID, true, map[string]interface{}{"active": body.Active})
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{"connectionId": body.ConnectionID, "active": body.Active}})
}

