[?2004lpackage main

import (
	"context"
	"time"
)

type planInput struct {
	originLat, originLng float64
	originType           string
	originNodeID         string
	sampleTypeID         string
	requiresCooled       bool
	batchingAllowed      bool
	deadline             time.Time
	alreadySealed         bool
}

type planResult struct {
	journeyID         string
	targetLabID       string
	assignmentIDs     []string
	estimatedDelivery time.Time
	routeMode         string
	status            string
}

// planJourney computes a route and persists journey, stops, assignments, and capacity reservations.
func planJourney(ctx context.Context, in planInput) (*planResult, string) {
	nodes, edges, err := loadNetwork(ctx)
	if err != nil {
		return nil, "no_route"
	}
	accepts, _ := loadLabAcceptance(ctx)
	caps, _ := loadCapacity(ctx)

	var candidates []*locationNode
	if in.originType == "node" && in.originNodeID != "" {
		n := nodes[in.originNodeID]
		if n == nil || !n.Active {
			return nil, "invalid_route"
		}
		candidates = []*locationNode{n}
	} else {
		candidates = servingCollectionNodes(nodes, in.originLat, in.originLng)
	}
	if len(candidates) == 0 {
		return nil, "outside_service_coverage"
	}
	labExists := false
	for _, n := range nodes {
		if n.Laboratory && n.Active && accepts[n.ID] != nil && accepts[n.ID][in.sampleTypeID] {
			labExists = true
			break
		}
	}
	if !labExists {
		return nil, "no_accepting_laboratory"
	}
	var bestPath *routePath
	for _, start := range candidates {
		p, _ := findRoute(ctx, nodes, edges, accepts, caps, in.sampleTypeID, in.requiresCooled, start.ID, in.deadline)
		if p != nil {
			if bestPath == nil || p.TotalTime < bestPath.TotalTime {
				bestPath = p
			}
		}
	}
	if bestPath == nil {
		if !hasAnyCapacity(ctx, in.requiresCooled) {
			return nil, "capacity_exhausted"
		}
		if in.requiresCooled && !hasCooledRoute(edges) {
			return nil, "invalid_route"
		}
		return nil, "no_valid_route"
	}
	arrival := now().Add(time.Duration(bestPath.TotalTime) * time.Minute)
	if !in.deadline.IsZero() && arrival.After(in.deadline) {
		return nil, "delivery_deadline_exceeded"
	}
	targetLab := bestPath.Nodes[len(bestPath.Nodes)-1].ID

	// route mode
	routeMode := "direct"
	if len(bestPath.Edges) > 1 {
		routeMode = "multi_stop"
	}

	journeyID := newUUID()
	_, err = pool.Exec(ctx, `INSERT INTO journeys (journey_id, plan_version, route_mode, status, sample_id, target_laboratory_id, estimated_delivery_at, total_cost_units)
		VALUES ($1,1,$2,'planned',NULL,$3,$4,$5)`,
		journeyID, routeMode, targetLab, arrival, bestPath.TotalCost)
	if err != nil {
		return nil, "internal_error"
	}

	// reserve capacity on edges and intermediate nodes
	for _, e := range bestPath.Edges {
		_, _ = pool.Exec(ctx, `INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, units, cooled) VALUES ($1,$2,NULL,1,$3)`,
			e.ID, journeyID, in.requiresCooled)
	}
	for i, n := range bestPath.Nodes {
		if i == 0 || i == len(bestPath.Nodes)-1 {
			// start node pickup / lab; reserve handling capacity too
		}
		_, _ = pool.Exec(ctx, `INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, units, cooled) VALUES ($1,$2,NULL,1,$3)`,
			n.ID, journeyID, in.requiresCooled)
	}

	// create stops
	seq := 0
	stopIDs := []string{}
	for i, n := range bestPath.Nodes {
		seq++
		stopType := "handoff"
		if i == 0 {
			stopType = "pickup"
		} else if i == len(bestPath.Nodes)-1 {
			stopType = "delivery"
		}
		est := now().Add(time.Duration(cumulativeTime(bestPath, i)) * time.Minute)
		stopID := newUUID()
		_, _ = pool.Exec(ctx, `INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes) VALUES ($1,$2,$3,$4,$5,$6,$7)`,
			stopID, journeyID, n.ID, stopType, seq, est, n.HandlingMinutes)
		stopIDs = append(stopIDs, stopID)
	}

	assignmentIDs := []string{}
	aSeq := 0

	// collection assignment (if not already sealed and origin is home/clinic, or origin node pickup)
	if !in.alreadySealed {
		aSeq++
		startNode := bestPath.Nodes[0]
		collAID := newUUID()
		offerExp := now().Add(15 * time.Minute)
		workerID := findCollectionWorker(ctx, in.sampleTypeID, startNode.ID)
		_, _ = pool.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, node_location_id, worker_id, offered_worker_id, offer_expires_at)
			VALUES ($1,$2,NULL,'collection',$3,'offered',$4,$5,$5,$6,$6,$7)`,
			collAID, journeyID, aSeq, nodeOrOrigin(in, startNode), startNode.ID, workerID, offerExp)
		assignmentIDs = append(assignmentIDs, collAID)
		if workerID == "" {
			flagExceptionNoWorker(ctx, journeyID, "collection")
		}
	}

	// transport legs per edge, plus node assignments at intermediate nodes
	for i := range bestPath.Edges {
		e := bestPath.Edges[i]
		_ = e
		fromNode := bestPath.Nodes[i]
		toNode := bestPath.Nodes[i+1]
		aSeq++
		transAID := newUUID()
		workerID := findTransportWorker(ctx)
		offerExp := now().Add(15 * time.Minute)
		_, _ = pool.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, worker_id, offered_worker_id, offer_expires_at)
			VALUES ($1,$2,NULL,'transport',$3,'offered',$4,$5,$6,$6,$7)`,
			transAID, journeyID, aSeq, fromNode.ID, toNode.ID, workerID, offerExp)
		assignmentIDs = append(assignmentIDs, transAID)
		if workerID == "" {
			flagExceptionNoWorker(ctx, journeyID, "transport")
		}
		// node assignment at destination node if it's an intermediate (not the lab)
		if i < len(bestPath.Edges)-1 {
			aSeq++
			nodeAID := newUUID()
			nodeWorker := findNodeWorker(ctx, toNode.ID)
			offerExp2 := now().Add(15 * time.Minute)
			_, _ = pool.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, node_location_id, from_location_id, to_location_id, worker_id, offered_worker_id, offer_expires_at)
				VALUES ($1,$2,NULL,'node',$3,'offered',$4,$5,$6,$7,$7,$8)`,
				nodeAID, journeyID, aSeq, toNode.ID, fromNode.ID, bestPath.Nodes[i+2].ID, nodeWorker, offerExp2)
			assignmentIDs = append(assignmentIDs, nodeAID)
		}
	}

	// laboratory assignment at target lab
	aSeq++
	labAID := newUUID()
	labWorker := findLabWorker(ctx, targetLab)
	offerExp := now().Add(15 * time.Minute)
	_, _ = pool.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, laboratory_id, node_location_id, worker_id, offered_worker_id, offer_expires_at)
		VALUES ($1,$2,NULL,'laboratory',$3,'offered',$4,$4,$5,$5,$6)`,
		labAID, journeyID, aSeq, targetLab, labWorker, offerExp)
	assignmentIDs = append(assignmentIDs, labAID)
	if labWorker == "" {
		flagExceptionNoWorker(ctx, journeyID, "laboratory")
	}

	return &planResult{
		journeyID:         journeyID,
		targetLabID:       targetLab,
		assignmentIDs:     assignmentIDs,
		estimatedDelivery: arrival,
		routeMode:         routeMode,
		status:            "planned",
	}, ""
}

func cumulativeTime(p *routePath, idx int) int {
	t := 0
	for i := 0; i < idx; i++ {
		t += p.Edges[i].TravelMinutes
		t += p.Nodes[i+1].HandlingMinutes
	}
	return t
}

func nodeOrOrigin(in planInput, startNode *locationNode) string {
	if in.originType == "node" {
		return startNode.ID
	}
	return "" // origin coordinate; store null
}

func flagExceptionNoWorker(ctx context.Context, journeyID, kind string) {
	_, _ = pool.Exec(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, payload) VALUES ('exception','journey',$1,$2::jsonb)`,
		journeyID, `{"reason":"no_qualified_worker","kind":"`+kind+`"}`)
}

// findCollectionWorker returns the first eligible, available certified collection professional.
func findCollectionWorker(ctx context.Context, sampleTypeID, nodeID string) string {
	var reqQual string
	_ = pool.QueryRow(ctx, `SELECT required_qualification FROM sample_types WHERE sample_type_id=$1`, sampleTypeID).Scan(&reqQual)
	if reqQual == "" {
		reqQual = "collect-" + sampleTypeID
	}
	row := pool.QueryRow(ctx, `SELECT u.user_id FROM users u WHERE u.active=true AND 'collection_professional'=ANY(u.roles) AND $1=ANY(u.qualifications) AND EXISTS (SELECT 1 FROM certifications c WHERE c.user_id=u.user_id AND c.code=$1 AND c.active=true) LIMIT 1`, reqQual)
	var id string
	if err := row.Scan(&id); err != nil {
		return ""
	}
	return id
}

func findTransportWorker(ctx context.Context) string {
	var id string
	_ = pool.QueryRow(ctx, `SELECT u.user_id FROM users u WHERE u.active=true AND 'delivery_partner'=ANY(u.roles) LIMIT 1`).Scan(&id)
	return id
}

func findNodeWorker(ctx context.Context, nodeID string) string {
	var id string
	_ = pool.QueryRow(ctx, `SELECT u.user_id FROM users u WHERE u.active=true AND 'node_handler'=ANY(u.roles) AND u.assigned_location_id=$1 LIMIT 1`, nodeID).Scan(&id)
	return id
}

func findLabWorker(ctx context.Context, labID string) string {
	var id string
	_ = pool.QueryRow(ctx, `SELECT u.user_id FROM users u WHERE u.active=true AND 'laboratory_team'=ANY(u.roles) AND u.assigned_location_id=$1 LIMIT 1`, labID).Scan(&id)
	return id
}[?2004h

[?2004lpackage main

import (
	"context"
	"encoding/json"
	"math"
	"net/http"
	"sync/atomic"
	"time"
)

var netRevision int64 = 1

func bumpNetworkRevision() {
	atomic.AddInt64(&netRevision, 1)
}

func recomputeServiceabilityAsync(ctx context.Context) {
	bumpNetworkRevision()
	go func() {
		_ = recomputeServiceability(context.Background())
	}()
}

type locationNode struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	CollectionPoint bool
	TransferPoint   bool
	Hub             bool
	Laboratory      bool
}

type connectionEdge struct {
	ID            string
	From, To      string
	TravelMinutes int
	Cost          float64
	Cooled        bool
	Active        bool
}

func loadNetwork(ctx context.Context) (map[string]*locationNode, []*connectionEdge, error) {
	nodes := map[string]*locationNode{}
	rows, err := pool.Query(ctx, `SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations`)
	if err != nil {
		return nil, nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var n locationNode
