// withAuth wraps a handler function with the requireAuth middleware and returns
// an http.HandlerFunc so it can be registered with mux.HandleFunc.
func withAuth(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		requireAuth(h).ServeHTTP(w, r)
	}
}

func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		next.ServeHTTP(w, r)
	})
}

// methodGuard restricts POST endpoints that are not GET/WS to POST only.
func methodGuard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		if strings.HasPrefix(path, "/api/") {
			allowedAny := strings.HasPrefix(path, "/api/read-sample-state/") ||
				strings.HasPrefix(path, "/api/read-user/")
			switch path {
			case "/api/ui/bootstrap", "/api/read-serviceability-snapshot", "/api/events", "/ready":
				allowedAny = true
			}
			if !allowedAny && r.Method != http.MethodPost {
				errResp(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
				return
			}
		}
		next.ServeHTTP(w, r)
	})
