func loadSampleState(r *http.Request, sampleID string) (map[string]interface{}, bool) {
	var requestID, requesterID, sampleTypeID, container, originType, status, deadline, requestedAt string
	var lat, lng, tMin, tMax float64
	var holderID, targetLab *string
	var locAt *string
	var incompat []string
	var serviceable bool
	err := pool.QueryRow(r.Context(),
		`SELECT s.request_id, s.requester_id, s.sample_type_id, s.container_type, s.origin_type, s.status, s.delivery_deadline::text, s.temperature_min_c, s.temperature_max_c, s.current_holder_id, s.latest_lat, s.latest_lng, s.location_recorded_at::text, r.serviceable, r.target_laboratory_id, r.incompatible_sample_types, r.requested_at::text
		 FROM samples s JOIN requests r ON r.sample_id=s.sample_id WHERE s.sample_id=$1`, sampleID).
		Scan(&requestID, &requesterID, &sampleTypeID, &container, &originType, &status, &deadline, &tMin, &tMax, &holderID, &lat, &lng, &locAt, &serviceable, &targetLab, &incompat, &requestedAt)
	if err != nil {
		return nil, false
	}
	activeIDs := []string{}
	rows, _ := pool.Query(r.Context(), `SELECT assignment_id::text FROM assignments WHERE sample_id=$1 AND status NOT IN ('completed','cancelled','declined')`, sampleID)
	if rows != nil {
		for rows.Next() {
			var a string
			_ = rows.Scan(&a)
			activeIDs = append(activeIDs, a)
		}
		rows.Close()
	}
	data := map[string]interface{}{
		"sampleId":                sampleID,
		"requestId":               requestID,
		"requesterId":             requesterID,
		"origin":                  coordObj(lat, lng),
		"originType":              originType,
		"requestedAt":             requestedAt,
		"deliveryDeadline":        deadline,
		"sampleTypeId":            sampleTypeID,
		"containerType":           container,
		"temperatureMinC":         tMin,
		"temperatureMaxC":         tMax,
		"incompatibleSampleTypes": incompat,
		"serviceability":          boolStr(serviceable),
		"activeAssignmentIds":     activeIDs,
		"state":                   map[string]interface{}{"status": status},
		"timeline":                buildTimeline(r.Context(), "sample", sampleID),
		"locationStale":           isStale(ptrStrVal(locAt)),
	}
	jid := journeyOfSample(r, sampleID)
	if jid != "" {
		data["activeJourneyId"] = jid
	}
	if targetLab != nil {
		data["targetLaboratoryId"] = *targetLab
	}
	if locAt != "" {
		data["latestLocation"] = coordObj(lat, lng)
		data["locationRecordedAt"] = *locAt
	}
	return data, true
}

