package main

import (
	"net/http"
	"strings"
)

func handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	sampleID := strings.TrimPrefix(r.URL.Path, "/api/read-sample-state/")
	if sampleID == "" {
		errResp(w, http.StatusNotFound, "not_found", "sampleId required")
		return
	}
	data, ok := loadSampleState(r, sampleID)
	if !ok {
		errResp(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	// requesters see only their own
	if ru.ActiveRole == "requester" {
		if data["requesterId"] != ru.UserID {
			errResp(w, http.StatusForbidden, "forbidden", "not your sample")
			return
		}
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": data})
}

func loadSampleState(r *http.Request, sampleID string) (map[string]interface{}, bool) {
	var requestID, requesterID, sampleTypeID, container, originType, status, deadline, requestedAt string
	var lat, lng, tMin, tMax float64
	var holderID, targetLab *string
	var locAt *string
	var incompat []string
	var serviceable bool
	err := pool.QueryRow(r.Context(),
		`SELECT s.request_id, s.requester_id, s.sample_type_id, s.container_type, s.origin_type, s.status, s.delivery_deadline::text, s.temperature_min_c, s.temperature_max_c, s.current_holder_id, s.latest_lat, s.latest_lng, s.location_recorded_at::text, r.serviceable, r.target_laboratory_id, r.incompatible_sample_types, r.requested_at::text
		 FROM samples s JOIN requests r ON r.sample_id=s.sample_id WHERE s.sample_id=$1`, sampleID).
		Scan(&requestID, &requesterID, &sampleTypeID, &container, &originType, &status, &deadline, &tMin, &tMax, &holderID, &lat, &lng, &locAt, &serviceable, &targetLab, &incompat, &requestedAt)
	if err != nil {
		return nil, false
	}
	activeIDs := []string{}
	rows, _ := pool.Query(r.Context(), `SELECT assignment_id::text FROM assignments WHERE sample_id=$1 AND status NOT IN ('completed','cancelled','declined')`, sampleID)
	if rows != nil {
		for rows.Next() {
			var a string
			_ = rows.Scan(&a)
			activeIDs = append(activeIDs, a)
		}
		rows.Close()
	}
	data := map[string]interface{}{
		"sampleId":                sampleID,
		"requestId":               requestID,
		"requesterId":             requesterID,
		"origin":                  coordObj(lat, lng),
		"originType":              originType,
		"requestedAt":             requestedAt,
		"deliveryDeadline":        deadline,
		"sampleTypeId":            sampleTypeID,
		"containerType":           container,
		"temperatureMinC":         tMin,
		"temperatureMaxC":         tMax,
		"incompatibleSampleTypes": incompat,
		"serviceability":          boolStr(serviceable),
		"activeAssignmentIds":     activeIDs,
		"state":                   map[string]interface{}{"status": status},
		"timeline":                buildTimeline(r.Context(), "sample", sampleID),
		"locationStale":           isStale(ptrStrVal(locAt)),
	}
	jid := journeyOfSample(r, sampleID)
	if jid != "" {
		data["activeJourneyId"] = jid
	}
	if targetLab != nil {
		data["targetLaboratoryId"] = *targetLab
	}
	if locAt != "" {
		data["latestLocation"] = coordObj(lat, lng)
		data["locationRecordedAt"] = *locAt
	}
	return data, true
}

func handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var body struct {
		SampleID string `json:"sampleId"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.SampleID == "" {
		errResp(w, http.StatusBadRequest, "invalid_json", "sampleId required")
		return
	}
	ru := current(r)
	var status string
	var sealed bool
	var holderID, requestID *string
	var lat, lng float64
	var locAt *string
	err := pool.QueryRow(r.Context(),
		`SELECT status, sealed, current_holder_id, request_id, latest_lat, latest_lng, location_recorded_at::text FROM samples WHERE sample_id=$1`, body.SampleID).
		Scan(&status, &sealed, &holderID, &requestID, &lat, &lng, &locAt)
	if err != nil {
		errResp(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if ru.ActiveRole == "requester" {
		var req string
		_ = pool.QueryRow(r.Context(), `SELECT requester_id::text FROM samples WHERE sample_id=$1`, body.SampleID).Scan(&req)
		if req != ru.UserID {
			errResp(w, http.StatusForbidden, "forbidden", "not your sample")
			return
		}
	}

	completedLegs := []string{}
	rows, _ := pool.Query(r.Context(), `SELECT assignment_id::text FROM assignments WHERE sample_id=$1 AND status='completed' ORDER BY sequence`, body.SampleID)
	if rows != nil {
		for rows.Next() {
			var a string
			_ = rows.Scan(&a)
			completedLegs = append(completedLegs, a)
		}
		rows.Close()
	}

	activeReplacement := []string{}
	rows, _ = pool.Query(r.Context(), `SELECT j.journey_id::text FROM journeys j JOIN samples s ON s.sample_id=$1 WHERE j.parent_journey_id IS NOT NULL AND j.status='planned'`, body.SampleID)
	_ = rows

	data := map[string]interface{}{
		"sampleId":                 body.SampleID,
		"status":                  status,
		"sealed":                  sealed,
		"completedLegIds":         completedLegs,
		"activeReplacementPlanIds": activeReplacement,
		"timeline":                buildTimeline(r.Context(), "sample", body.SampleID),
		"locationStale":           isStale(ptrStrVal(locAt)),
	}
	if holderID != nil {
		data["currentHolderId"] = *holderID
	}
	if requestID != nil {
		data["activeJourneyId"] = journeyOfSample(r, *requestID)
	}
	latestLoc := coordObj(lat, lng)
	if locAt != nil {
		data["latestLocation"] = latestLoc
		data["locationRecordedAt"] = *locAt
	}
	// pending handoff
	var phID *string
	_ = pool.QueryRow(r.Context(), `SELECT handoff_id::text FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY initiated_at DESC LIMIT 1`, body.SampleID).Scan(&phID)
	if phID != nil {
		data["pendingHandoffId"] = *phID
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": data})
}

func ptrStrVal(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

func journeyOfSample(r *http.Request, sampleID string) string {
	var jid string
	_ = pool.QueryRow(r.Context(), `SELECT journey_id::text FROM journeys WHERE sample_id=$1 ORDER BY plan_version DESC LIMIT 1`, sampleID).Scan(&jid)
	return jid
}

func handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		JourneyID string `json:"journeyId"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	if body.JourneyID == "" {
		errResp(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	plan := buildJourneyPlan(r.Context(), body.JourneyID)
	if plan == nil {
		errResp(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": plan})
}

func handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "dispatcher" && ru.ActiveRole != "administrator" {
		errResp(w, http.StatusForbidden, "forbidden", "dispatcher role required")
		return
	}
	var body struct {
		Filters struct {
			SampleTypeID string `json:"sampleTypeId"`
		} `json:"filters"`
	}
	// body optional
	_ = parseJSONBody(r, &body)

	samples := []map[string]interface{}{}
	q := `SELECT sample_id, request_id, COALESCE(origin_lat,0), COALESCE(origin_lng,0), status, current_holder_id::text, COALESCE(latest_lat,0), COALESCE(latest_lng,0), location_recorded_at::text, delivery_deadline::text FROM samples`
	args := []interface{}{}
	if body.Filters.SampleTypeID != "" {
		q += ` WHERE sample_type_id=$1`
		args = append(args, body.Filters.SampleTypeID)
	}
	rows, err := pool.Query(r.Context(), q, args...)
	if err == nil {
		for rows.Next() {
			var sid, rid, status, holder, deadline, locAt string
			var olat, olng, lat, lng float64
			_ = rows.Scan(&sid, &rid, &olat, &olng, &status, &holder, &lat, &lng, &locAt, &deadline)
			jid := journeyOfSample(r, sid)
			m := map[string]interface{}{
				"sampleId":          sid,
				"status":            status,
				"locationStale":     isStale(locAt),
				"origin":            coordObj(olat, olng),
				"deliveryDeadline":  deadline,
			}
			if holder != "" {
				m["currentHolderId"] = holder
			}
			if jid != "" {
				m["activeJourneyId"] = jid
			}
			if locAt != "" {
				m["latestLocation"] = coordObj(lat, lng)
				m["locationRecordedAt"] = locAt
			}
			samples = append(samples, m)
		}
		rows.Close()
	}

	workers := []map[string]interface{}{}
	wrows, _ := pool.Query(r.Context(), `SELECT user_id, COALESCE(full_name,''), roles, available, capacity_units, COALESCE(latest_lat,0), COALESCE(latest_lng,0), location_recorded_at::text FROM users`, )
	_ = wrows
	wrows, _ = pool.Query(r.Context(), `SELECT u.user_id, COALESCE(u.full_name,''), u.roles, u.available, u.capacity_units, COALESCE(wl.latitude,0), COALESCE(wl.longitude,0), COALESCE(wl.recorded_at::text,'') FROM users u LEFT JOIN LATERAL (SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=u.user_id ORDER BY sequence DESC LIMIT 1) wl ON true`)
	if wrows != nil {
		for wrows.Next() {
			var wid, name, locAt string
			var roles []string
			var available bool
			var cap int
			var lat, lng float64
			_ = wrows.Scan(&wid, &name, &roles, &available, &cap, &lat, &lng, &locAt)
			var ac int
			_ = pool.QueryRow(r.Context(), `SELECT count(*) FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled','declined')`, wid).Scan(&ac)
			st := "unavailable"
			if available {
				st = "available"
			}
			m := map[string]interface{}{
				"workerId":        wid,
				"fullName":        name,
				"roles":           roles,
				"available":       available,
				"status":          st,
				"capacityUnits":   cap,
				"assignmentCount": ac,
				"locationStale":   isStale(locAt),
			}
			if locAt != "" {
				m["latestLocation"] = coordObj(lat, lng)
				m["locationRecordedAt"] = locAt
			}
			workers = append(workers, m)
		}
		wrows.Close()
	}

	locations := []map[string]interface{}{}
	lrows, _ := pool.Query(r.Context(), `SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations`)
	if lrows != nil {
		for lrows.Next() {
			var id, name string
			var lat, lng, cov float64
			var handling int
			var active, cp, tp, h, l bool
			_ = lrows.Scan(&id, &name, &lat, &lng, &cov, &handling, &active, &cp, &tp, &h, &l)
			m := map[string]interface{}{
				"id":              id,
				"locationId":      id,
				"name":            name,
				"coordinate":      coordObj(lat, lng),
				"active":          active,
				"coverageKm":      cov,
				"handlingMinutes": handling,
				"functions": map[string]interface{}{
					"collection_point": cp,
					"transfer_point":   tp,
					"hub":              h,
					"laboratory":       l,
				},
				"capacity": buildCapacity(r.Context(), id),
			}
			// accepted sample types
			acc := []string{}
			arows, _ := pool.Query(r.Context(), `SELECT sample_type_id::text FROM laboratory_acceptance WHERE laboratory_id=$1 AND accepts=true`, id)
			if arows != nil {
				for arows.Next() {
					var st string
					_ = arows.Scan(&st)
					acc = append(acc, st)
				}
				arows.Close()
			}
			m["acceptedSampleTypeIds"] = acc
			locations = append(locations, m)
		}
		lrows.Close()
	}

	connections := []map[string]interface{}{}
	crows, _ := pool.Query(r.Context(), `SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if crows != nil {
		for crows.Next() {
			var id, from, to string
			var min int
			var cost float64
			var cooled, active bool
			_ = crows.Scan(&id, &from, &to, &min, &cost, &cooled, &active)
			connections = append(connections, map[string]interface{}{
				"id":            id,
				"connectionId":  id,
				"fromLocationId": from,
				"toLocationId":   to,
				"travelMinutes":  min,
				"costUnits":      cost,
				"cooled":         cooled,
				"active":         active,
				"capacity":       buildCapacity(r.Context(), id),
			})
		}
		crows.Close()
	}

	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"samples":     samples,
		"workers":    workers,
		"locations":  locations,
		"connections": connections,
	}})
}

func handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = parseJSONBody(r, &body)
	role := body.Role
	if role == "" {
		role = ru.ActiveRole
	}
	if !contains(ru.Roles, role) {
		errResp(w, http.StatusForbidden, "forbidden", "role not held")
		return
	}

	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	switch role {
	case "requester":
		rows, _ := pool.Query(r.Context(), `SELECT sample_id, request_id, status, serviceable, requested_at::text, delivery_deadline::text FROM requests WHERE requester_id=$1 ORDER BY created_at DESC`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var sid, rid, status string
				var serviceable bool
				var reqAt, deadline string
				_ = rows.Scan(&sid, &rid, &status, &serviceable, &reqAt, &deadline)
				item := map[string]interface{}{
					"kind":            "sample",
					"sampleId":        sid,
					"requestId":       rid,
					"status":          status,
					"serviceability":  boolStr(serviceable),
					"requestedAt":     reqAt,
					"deliveryDeadline": deadline,
					"history":         buildTimeline(r.Context(), "sample", sid),
					"locationStale":    true,
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "collection_professional":
		rows, _ := pool.Query(r.Context(), `SELECT a.assignment_id, a.sample_id, a.status, a.journey_id, a.offer_expires_at::text FROM assignments a WHERE a.offered_worker_id=$1 OR a.worker_id=$1`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var aid, sid, status string
				var jid *string
				var exp *string
				_ = rows.Scan(&aid, &sid, &status, &jid, &exp)
				item := map[string]interface{}{
					"kind":          "collection",
					"assignmentId":  aid,
					"sampleId":      sid,
					"status":        status,
					"history":       buildTimeline(r.Context(), "assignment", aid),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				if exp != nil {
					item["offerExpiresAt"] = *exp
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "delivery_partner":
		rows, _ := pool.Query(r.Context(), `SELECT a.assignment_id, a.sample_id, a.status, a.journey_id, a.from_location_id, a.to_location_id, a.sequence FROM assignments a WHERE a.kind='transport' AND (a.offered_worker_id=$1 OR a.worker_id=$1)`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var aid, sid, status string
				var seq int
				var jid, from, to *string
				_ = rows.Scan(&aid, &sid, &status, &jid, &from, &to, &seq)
				item := map[string]interface{}{
					"kind":          "transport",
					"assignmentId":  aid,
					"sampleId":      sid,
					"status":        status,
					"sequence":      seq,
					"history":       buildTimeline(r.Context(), "assignment", aid),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				if from != nil {
					item["fromLocationId"] = *from
				}
				if to != nil {
					item["toLocationId"] = *to
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "node_handler":
		rows, _ := pool.Query(r.Context(), `SELECT a.assignment_id, a.sample_id, a.status, a.journey_id, a.node_location_id, a.from_location_id, a.to_location_id FROM assignments a WHERE a.kind='node' AND (a.offered_worker_id=$1 OR a.worker_id=$1)`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var aid, sid, status string
				var jid, node, from, to *string
				_ = rows.Scan(&aid, &sid, &status, &jid, &node, &from, &to)
				item := map[string]interface{}{
					"kind":          "node",
					"assignmentId":  aid,
					"sampleId":      sid,
					"status":        status,
					"history":       buildTimeline(r.Context(), "assignment", aid),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				if node != nil {
					item["nodeId"] = *node
				}
				if from != nil {
					item["incomingFromLocationId"] = *from
				}
				if to != nil {
					item["outgoingToLocationId"] = *to
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "laboratory_team":
		rows, _ := pool.Query(r.Context(), `SELECT a.assignment_id, a.sample_id, a.status, a.journey_id, a.laboratory_id FROM assignments a WHERE a.kind='laboratory' AND (a.offered_worker_id=$1 OR a.worker_id=$1)`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var aid, sid, status string
				var jid, lab *string
				_ = rows.Scan(&aid, &sid, &status, &jid, &lab)
				item := map[string]interface{}{
					"kind":          "laboratory",
					"assignmentId":  aid,
					"sampleId":      sid,
					"status":        status,
					"history":       buildTimeline(r.Context(), "assignment", aid),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				if lab != nil {
					item["laboratoryId"] = *lab
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "dispatcher", "administrator":
		jrows, _ := pool.Query(r.Context(), `SELECT journey_id, status, route_mode, plan_version, COALESCE(estimated_delivery_at::text,''), COALESCE(total_cost_units,0) FROM journeys ORDER BY created_at DESC`)
		if jrows != nil {
			for jrows.Next() {
				var jid, status, routeMode string
				var pv int
				var est string
				var cost float64
				_ = jrows.Scan(&jid, &status, &routeMode, &pv, &est, &cost)
				sids := []string{}
				srows, _ := pool.Query(r.Context(), `SELECT DISTINCT COALESCE(sample_id::text,'') FROM assignments WHERE journey_id=$1 AND sample_id IS NOT NULL`, jid)
				if srows != nil {
					for srows.Next() {
						var s string
						_ = srows.Scan(&s)
						if s != "" {
							sids = append(sids, s)
						}
					}
					srows.Close()
				}
				var ac int
				_ = pool.QueryRow(r.Context(), `SELECT count(*) FROM assignments WHERE journey_id=$1`, jid).Scan(&ac)
				item := map[string]interface{}{
					"kind":               "journey",
					"journeyId":          jid,
					"status":             status,
					"routeMode":          routeMode,
					"planVersion":        pv,
					"sampleIds":          sids,
					"estimatedDeliveryAt": est,
					"assignmentCount":    ac,
					"history":            buildTimeline(r.Context(), "journey", jid),
				}
				switch status {
				case "planned", "offered":
					pending = append(pending, item)
				case "completed", "cancelled", "expired":
					completed = append(completed, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
			jrows.Close()
		}
	}

	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	}})
}

func classifyItem(status string, item map[string]interface{}, pending, inProgress, completed *[]map[string]interface{}) {
	switch status {
	case "offered", "planned":
		*pending = append(*pending, item)
	case "completed", "cancelled", "declined", "expired":
		*completed = append(*completed, item)
	default:
		*inProgress = append(*inProgress, item)
	}
}

func boolStr(b bool) string {
	if b {
		return "serviceable"
	}
	return "unserviceable"
}

func handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "dispatcher" && ru.ActiveRole != "administrator" {
		errResp(w, http.StatusForbidden, "forbidden", "dispatcher role required")
		return
	}
	var body struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		writeAPIError(w, err)
		return
	}
	limit := body.Limit
	if limit == 0 {
		limit = 500
	}
	if limit < 1 || limit > 5000 {
		errResp(w, http.StatusBadRequest, "invalid_limit", "limit out of range")
		return
	}
	if body.Offset < 0 {
		errResp(w, http.StatusBadRequest, "invalid_offset", "offset negative")
		return
	}
	order := body.Order
	if order == "" {
		order = "newest_first"
	}
	if order != "newest_first" && order != "oldest_first" {
		errResp(w, http.StatusBadRequest, "invalid_order", "order must be newest_first or oldest_first")
		return
	}

	where := []string{"1=1"}
	args := []interface{}{}
	ai := 1
	add := func(cond string, val interface{}) {
		where = append(where, cond)
		args = append(args, val)
		ai++
	}
	if body.Query != "" {
		add(`(action ILIKE $`+itoa(ai)+` OR entity_id ILIKE $`+itoa(ai)+` OR details::text ILIKE $`+itoa(ai)+`)`, "%"+body.Query+"%")
	}
	if body.ActorID != "" {
		add(`actor_id::text = $`+itoa(ai), body.ActorID)
	}
	if body.EntityType != "" {
		add(`entity_type = $`+itoa(ai), body.EntityType)
	}
	if body.EntityID != "" {
		add(`entity_id = $`+itoa(ai), body.EntityID)
	}
	if body.Action != "" {
		add(`action = $`+itoa(ai), body.Action)
	}
	if body.Role != "" {
		add(`actor_role = $`+itoa(ai), body.Role)
	}
	if body.Success != nil {
		add(`success = $`+itoa(ai), *body.Success)
	}
	if body.FromTime != "" {
		if t, err := parseRFC3339(body.FromTime); err == nil {
			add(`occurred_at >= $`+itoa(ai), t)
		} else {
			errResp(w, http.StatusBadRequest, "invalid_time", "invalid fromTime")
			return
		}
	}
	if body.ToTime != "" {
		if t, err := parseRFC3339(body.ToTime); err == nil {
			add(`occurred_at <= $`+itoa(ai), t)
		} else {
			errResp(w, http.StatusBadRequest, "invalid_time", "invalid toTime")
			return
		}
	}

	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}

	var total int
	_ = pool.QueryRow(r.Context(), `SELECT count(*) FROM audit_log WHERE `+strings.Join(where, " AND "), args...).Scan(&total)

	qargs := append([]interface{}{}, args...)
	qargs = append(qargs, limit, body.Offset)
	rows, err := pool.Query(r.Context(),
		`SELECT audit_id, COALESCE(actor_id::text,''), actor_role, action, entity_type, entity_id, success, occurred_at::text, details FROM audit_log WHERE `+
			strings.Join(where, " AND ")+` ORDER BY occurred_at `+dir+`, audit_id `+dir+` LIMIT $`+itoa(ai)+` OFFSET $`+itoa(ai+1), qargs...)
	entries := []map[string]interface{}{}
	if err == nil {
		for rows.Next() {
			var auditID, actorID, actorRole, action, etype, eID, occurred string
			var success bool
			var details []byte
			_ = rows.Scan(&auditID, &actorID, &actorRole, &action, &etype, &eID, &success, &occurred, &details)
			entries = append(entries, map[string]interface{}{
				"auditId":     auditID,
				"actorId":     actorID,
				"role":        actorRole,
				"actorRole":   actorRole,
				"action":      action,
				"entityType":  etype,
				"entityId":    eID,
				"success":     success,
				"occurredAt":  occurred,
				"details":     jsonBytes(details),
			})
		}
		rows.Close()
	}

	returned := len(entries)
	hasMore := body.Offset+returned < total
	nextOffset := body.Offset + returned
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"entries":    entries,
		"total":      total,
		"returned":   returned,
		"offset":     body.Offset,
		"limit":      limit,
		"order":      order,
		"hasMore":    hasMore,
		"nextOffset": nextOffset,
	}})
}

func itoa(i int) string {
	return intToStr(i)
}

func intToStr(i int) string {
	// avoid strconv import churn; reuse
	return intStr(i)
}

