// reofferAssignment creates a fresh offered assignment for the next eligible worker.
func reofferAssignment(r *http.Request, oldAID, journeyID string) string {
	var kind, fromLoc, toLoc, nodeLoc, labLoc, sampleTypeID string
	var seq int
	_ = pool.QueryRow(r.Context(), `SELECT kind, sequence, from_location_id::text, to_location_id::text, node_location_id::text, laboratory_id::text FROM assignments WHERE assignment_id=$1`, oldAID).
		Scan(&kind, &seq, &fromLoc, &toLoc, &nodeLoc, &labLoc)
	var sampleID *string
	_ = pool.QueryRow(r.Context(), `SELECT sample_id::text FROM assignments WHERE assignment_id=$1`, oldAID).Scan(&sampleID)
	var sid interface{}
	if sampleID != nil && *sampleID != "" {
		sid = *sampleID
	}
	var workerID string
	switch kind {
	case "collection":
		if sampleID != nil {
			_ = pool.QueryRow(r.Context(), `SELECT sample_type_id::text FROM samples WHERE sample_id=$1`, *sampleID).Scan(&sampleTypeID)
			workerID = findCollectionWorkerExcl(r.Context(), sampleTypeID, "", ru0(oldAID))
		}
	case "transport":
		workerID = findTransportWorkerExcl(r.Context(), "")
	case "node":
		workerID = findNodeWorkerExcl(r.Context(), nodeLoc, "")
	case "laboratory":
		workerID = findLabWorkerExcl(r.Context(), labLoc, "")
	}
	newAID := newUUID()
	offerExp := now().Add(15 * time.Minute)
	_, _ = pool.Exec(r.Context(),
		`INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, node_location_id, laboratory_id, worker_id, offered_worker_id, offer_expires_at)
		 VALUES ($1,$2,$3,$4,$5,'offered',$6,$7,$8,$9,$10,$10,$11)`,
		newAID, journeyID, sid, kind, seq, strOrNull(fromLoc), strOrNull(toLoc), strOrNull(nodeLoc), strOrNull(labLoc), workerID, offerExp)
	return workerID
}

