		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	var kind, status, offeredWorker string
	var workerID *string
	err := pool.QueryRow(r.Context(), `SELECT kind, status, offered_worker_id::text, worker_id::text FROM assignments WHERE assignment_id=$1`, body.AssignmentID).
		Scan(&kind, &status, &offeredWorker, &workerID)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "offered" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "offer_not_available", "assignment not offered")
		return
	}
	if offeredWorker != ru.UserID {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusForbidden, "ineligible_worker", "not offered to you")
		return
	}
	// eligibility checks for node/lab assignments
	if kind == "node" {
		var assignedLoc *string
		_ = pool.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, ru.UserID).Scan(&assignedLoc)
		var nodeLoc string
		_ = pool.QueryRow(r.Context(), `SELECT node_location_id::text FROM assignments WHERE assignment_id=$1`, body.AssignmentID).Scan(&nodeLoc)
		if assignedLoc == nil || *assignedLoc != nodeLoc {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusForbidden, "ineligible_worker", "not assigned to node")
			return
		}
	}
	if kind == "laboratory" {
		var assignedLoc *string
		_ = pool.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, ru.UserID).Scan(&assignedLoc)
		var labID string
		_ = pool.QueryRow(r.Context(), `SELECT laboratory_id::text FROM assignments WHERE assignment_id=$1`, body.AssignmentID).Scan(&labID)
		if assignedLoc == nil || *assignedLoc != labID {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusForbidden, "ineligible_worker", "not assigned to laboratory")
			return
		}
	}
	ct, err := pool.Exec(r.Context(), `UPDATE assignments SET status='accepted', worker_id=$2, accepted_at=$3 WHERE assignment_id=$1 AND status='offered'`,
		body.AssignmentID, ru.UserID, now())
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if ct.RowsAffected() == 0 {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "offer_not_available", "assignment taken")
		return
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "accept_assignment", "assignment", body.AssignmentID, true, nil)
	data := map[string]interface{}{
		"assignmentId": body.AssignmentID,
		"workerId":     ru.UserID,
		"status":       "accepted",
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		AssignmentID   string  `json:"assignmentId"`
		Reason         string  `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	var status, offeredWorker, journeyID string
	err := pool.QueryRow(r.Context(), `SELECT status, offered_worker_id::text, journey_id::text FROM assignments WHERE assignment_id=$1`, body.AssignmentID).
		Scan(&status, &offeredWorker, &journeyID)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "offered" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "offer_not_available", "assignment not offered")
		return
	}
	declinedAt := now()
	if body.DeclinedAt != nil {
		if t, err := parseRFC3339(*body.DeclinedAt); err == nil {
			declinedAt = t
		} else {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_time", "invalid declinedAt")
			return
		}
	}
	// reoffer to next eligible worker
	reofferTo := reofferAssignment(r, body.AssignmentID, journeyID)
	_, _ = pool.Exec(r.Context(), `UPDATE assignments SET status='declined' WHERE assignment_id=$1`, body.AssignmentID)
	audit(r.Context(), ru.UserID, ru.ActiveRole, "decline_assignment", "assignment", body.AssignmentID, true, map[string]interface{}{"reason": body.Reason})
	data := map[string]interface{}{
		"assignmentId": body.AssignmentID,
		"status":       "pending",
		"declinedBy":   ru.UserID,
		"declinedAt":   declinedAt.Format(time.RFC3339),
	}
	if reofferTo != "" {
		data["reofferedTo"] = reofferTo
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

// reofferAssignment creates a fresh offered assignment for the next eligible worker.
func reofferAssignment(r *http.Request, oldAID, journeyID string) string {
	var kind, fromLoc, toLoc, nodeLoc, labLoc, sampleTypeID string
	var seq int
	_ = pool.QueryRow(r.Context(), `SELECT kind, sequence, from_location_id::text, to_location_id::text, node_location_id::text, laboratory_id::text FROM assignments WHERE assignment_id=$1`, oldAID).
		Scan(&kind, &seq, &fromLoc, &toLoc, &nodeLoc, &labLoc)
	var sampleID *string
	_ = pool.QueryRow(r.Context(), `SELECT sample_id::text FROM assignments WHERE assignment_id=$1`, oldAID).Scan(&sampleID)
	var sid interface{}
	if sampleID != nil && *sampleID != "" {
		sid = *sampleID
	}
	var workerID string
	switch kind {
	case "collection":
		if sampleID != nil {
			_ = pool.QueryRow(r.Context(), `SELECT sample_type_id::text FROM samples WHERE sample_id=$1`, *sampleID).Scan(&sampleTypeID)
			workerID = findCollectionWorkerExcl(r.Context(), sampleTypeID, "", ru0(oldAID))
		}
	case "transport":
		workerID = findTransportWorkerExcl(r.Context(), "")
	case "node":
		workerID = findNodeWorkerExcl(r.Context(), nodeLoc, "")
	case "laboratory":
		workerID = findLabWorkerExcl(r.Context(), labLoc, "")
	}
	newAID := newUUID()
	offerExp := now().Add(15 * time.Minute)
	_, _ = pool.Exec(r.Context(),
		`INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, node_location_id, laboratory_id, worker_id, offered_worker_id, offer_expires_at)
		 VALUES ($1,$2,$3,$4,$5,'offered',$6,$7,$8,$9,$10,$10,$11)`,
		newAID, journeyID, sid, kind, seq, strOrNull(fromLoc), strOrNull(toLoc), strOrNull(nodeLoc), strOrNull(labLoc), workerID, offerExp)
	return workerID
}

func ru0(aid string) string { return "" }

func strOrNull(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	if ru.ActiveRole != "collection_professional" && ru.ActiveRole != "administrator" {
		errResp(w, http.StatusForbidden, "forbidden", "collection role required")
		return
	}
	var body struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		CollectedAt           string  `json:"collectedAt"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		IdempotencyKey        string  `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	collectedAt, err := parseRFC3339(body.CollectedAt)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_time", "invalid collectedAt")
		return
	}
	// assignment must be accepted and belong to user
	var status, offeredWorker string
	err = pool.QueryRow(r.Context(), `SELECT status, offered_worker_id::text FROM assignments WHERE assignment_id=$1`, body.AssignmentID).Scan(&status, &offeredWorker)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "accepted" && status != "in_progress" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "collection_not_ready", "assignment not accepted")
		return
	}
	// check collection window
	var earliest, latest *string
	_ = pool.QueryRow(r.Context(), `SELECT earliest_collection_at::text, latest_collection_at::text FROM requests WHERE sample_id=$1`, body.SampleID).Scan(&earliest, &latest)
	if earliest != nil && !collectedAt.Before(parseMust(*earliest)) {
		if !collectedAt.After(parseMust(*earliest).Add(-time.Second)) {
		}
	}
	if earliest != nil {
		et := parseMust(*earliest)
		if !et.IsZero() && collectedAt.Before(et) {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "outside_collection_window", "collected before earliest")
			return
		}
	}
	if latest != nil {
		lt := parseMust(*latest)
		if !lt.IsZero() && collectedAt.After(lt) {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "outside_collection_window", "collected after latest")
			return
		}
	}
	// compliance check
	var tMin, tMax float64
	_ = pool.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1`, body.SampleID).Scan(&tMin, &tMax)
	compliant := body.ObservedTemperatureC >= tMin && body.ObservedTemperatureC <= tMax

	_, _ = pool.Exec(r.Context(), `UPDATE samples SET sealed=true, status='sealed', current_holder_id=$2, location_recorded_at=$3 WHERE sample_id=$1`,
		body.SampleID, ru.UserID, collectedAt)
	_, _ = pool.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE assignment_id=$1`, body.AssignmentID)
	_, _ = pool.Exec(r.Context(), `INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6)`,
		body.SampleID, body.AssignmentID, body.ContainerType, body.ObservedTemperatureC, compliant, collectedAt)

	audit(r.Context(), ru.UserID, ru.ActiveRole, "collect_and_seal", "sample", body.SampleID, true, map[string]interface{}{"compliant": compliant})
	emitEvent(r.Context(), "sample_sealed", "sample", body.SampleID, map[string]interface{}{"holderId": ru.UserID})
	data := map[string]interface{}{
		"sampleId":            body.SampleID,
		"status":              "sealed",
		"currentHolderId":     ru.UserID,
		"sealedAt":            collectedAt.Format(time.RFC3339),
		"handlingCompliant":   compliant,
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func parseMust(s string) time.Time {
	t, _ := parseRFC3339(s)
	return t
}

func handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		SampleID        string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID  string `json:"toAssignmentId"`
		ReceiverID      string `json:"receiverId"`
		IdempotencyKey  string `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	// check existing pending handoff for sample to avoid duplicates
	var existing string
	_ = pool.QueryRow(r.Context(), `SELECT handoff_id::text FROM handoffs WHERE sample_id=$1 AND from_assignment_id=$2 AND status='pending' ORDER BY initiated_at DESC LIMIT 1`, body.SampleID, body.FromAssignmentID).Scan(&existing)
	if existing != "" {
		// return existing
		data := map[string]interface{}{"handoffId": existing, "status": "pending"}
		storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
		jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
		return
	}
	handoffID := newUUID()
	_, err := pool.Exec(r.Context(), `INSERT INTO handoffs (handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed) VALUES ($1,$2,$3,$4,$5,$6,'pending',true)`,
		handoffID, body.SampleID, body.FromAssignmentID, body.ToAssignmentID, ru.UserID, body.ReceiverID)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "initiate_handoff", "sample", body.SampleID, true, map[string]interface{}{"handoffId": handoffID})
	data := map[string]interface{}{
		"handoffId":         handoffID,
		"status":            "pending",
		"senderConfirmed":   true,
		"receiverConfirmed": false,
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		HandoffID        string  `json:"handoffId"`
		ConfirmationSide string  `json:"confirmationSide"`
		ConfirmedAt      string  `json:"confirmedAt"`
		IdempotencyKey   string  `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if body.ConfirmationSide != "sender" && body.ConfirmationSide != "receiver" {
		errResp(w, http.StatusBadRequest, "invalid_confirmation_side", "must be sender or receiver")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	confirmedAt, err := parseRFC3339(body.ConfirmedAt)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_time", "invalid confirmedAt")
		return
	}
	var sampleID, senderID, receiverID, status string
	var senderConf, receiverConf bool
	err = pool.QueryRow(r.Context(), `SELECT sample_id::text, sender_id::text, receiver_id::text, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id=$1`, body.HandoffID).
		Scan(&sampleID, &senderID, &receiverID, &status, &senderConf, &receiverConf)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	if status == "confirmed" {
		data := map[string]interface{}{"handoffId": body.HandoffID, "status": "confirmed", "senderConfirmed": senderConf, "receiverConfirmed": receiverConf, "currentHolderId": receiverID}
		storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
		jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
		return
	}
	if body.ConfirmationSide == "sender" {
		if ru.UserID != senderID {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusForbidden, "forbidden", "not sender")
			return
		}
		senderConf = true
	} else {
		if ru.UserID != receiverID {
			writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusForbidden, "forbidden", "not receiver")
			return
		}
		receiverConf = true
	}
	confirmed := senderConf && receiverConf
	if confirmed {
		_, _ = pool.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=$2, receiver_confirmed=$3, status='confirmed', confirmed_at=$4 WHERE handoff_id=$1`, body.HandoffID, senderConf, receiverConf, confirmedAt)
		_, _ = pool.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2, location_recorded_at=$3 WHERE sample_id=$1`, sampleID, receiverID, confirmedAt)
		audit(r.Context(), ru.UserID, ru.ActiveRole, "confirm_handoff", "sample", sampleID, true, map[string]interface{}{"confirmed": true})
		emitEvent(r.Context(), "custody_transfer", "sample", sampleID, map[string]interface{}{"holderId": receiverID})
	} else {
		_, _ = pool.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=$2, receiver_confirmed=$3 WHERE handoff_id=$1`, body.HandoffID, senderConf, receiverConf)
		audit(r.Context(), ru.UserID, ru.ActiveRole, "confirm_handoff", "sample", sampleID, true, map[string]interface{}{"side": body.ConfirmationSide})
	}
	data := map[string]interface{}{
		"handoffId":         body.HandoffID,
		"senderConfirmed":   senderConf,
		"receiverConfirmed": receiverConf,
		"currentHolderId":   receiverID,
	}
	if confirmed {
		data["status"] = "confirmed"
	} else {
		data["status"] = "pending"
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
