		return
	}
	var body struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	receivedAt, err := parseRFC3339(body.ReceivedAt)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_time", "invalid receivedAt")
		return
	}
	// verify lab operator assigned
	var assignedLoc *string
	_ = pool.QueryRow(r.Context(), `SELECT assigned_location_id::text FROM users WHERE user_id=$1`, ru.UserID).Scan(&assignedLoc)
	if assignedLoc == nil || *assignedLoc != body.LaboratoryID {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusForbidden, "wrong_laboratory_operator", "not assigned to laboratory")
		return
	}
	var status, holderID string
	_ = pool.QueryRow(r.Context(), `SELECT status, COALESCE(current_holder_id::text,'') FROM samples WHERE sample_id=$1`, body.SampleID).Scan(&status, &holderID)
	if status == "" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "sample not found")
