	data := map[string]interface{}{
		"sampleId":      body.SampleID,
		"laboratoryId":  body.LaboratoryID,
		"status":        "received",
		"receivedAt":    receivedAt.Format(time.RFC3339),
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
