		return
	}
	var status, holderID string
	_ = pool.QueryRow(r.Context(), `SELECT status, COALESCE(current_holder_id::text,'') FROM samples WHERE sample_id=$1`, body.SampleID).Scan(&status, &holderID)
	if status == "" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	_, _ = pool.Exec(r.Context(), `UPDATE samples SET status='received', current_holder_id=$2, location_recorded_at=$3 WHERE sample_id=$1`, body.SampleID, ru.UserID, receivedAt)
	// complete laboratory assignment
	_, _ = pool.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$2 WHERE sample_id=$1 AND kind='laboratory'`, body.SampleID, receivedAt)
	_, _ = pool.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE sample_id=$1`, body.SampleID)
	audit(r.Context(), ru.UserID, ru.ActiveRole, "confirm_lab_receipt", "sample", body.SampleID, true, map[string]interface{}{"laboratoryId": body.LaboratoryID})
