func handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		AssignmentID string  `json:"assignmentId"`
		Coordinate   *coord  `json:"coordinate"`
		Sequence     int     `json:"sequence"`
		RecordedAt   string  `json:"recordedAt"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.Coordinate == nil {
		errResp(w, http.StatusBadRequest, "invalid_coordinate", "coordinate required")
		return
	}
	if body.Sequence < 1 {
		errResp(w, http.StatusBadRequest, "invalid_sequence", "sequence must be >= 1")
		return
	}
	recordedAt, err := parseRFC3339(body.RecordedAt)
	if err != nil {
		errResp(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}
	var exists string
	_ = pool.QueryRow(r.Context(), `SELECT assignment_id::text FROM assignments WHERE assignment_id=$1 AND worker_id=$2`, body.AssignmentID, ru.UserID).Scan(&exists)
	if exists == "" {
		errResp(w, http.StatusNotFound, "not_found", "assignment not found or not yours")
		return
	}
	// stale sequence check
	var maxSeq int
	_ = pool.QueryRow(r.Context(), `SELECT COALESCE(MAX(sequence),0) FROM worker_locations WHERE assignment_id=$1`, body.AssignmentID).Scan(&maxSeq)
	if body.Sequence <= maxSeq {
		errResp(w, http.StatusConflict, "stale_location", "sequence not newer")
		return
	}
	_, _ = pool.Exec(r.Context(), `INSERT INTO worker_locations (assignment_id, worker_id, latitude, longitude, sequence, recorded_at) VALUES ($1,$2,$3,$4,$5,$6)`,
		body.AssignmentID, ru.UserID, body.Coordinate.Latitude, body.Coordinate.Longitude, body.Sequence, recordedAt)
	audit(r.Context(), ru.UserID, ru.ActiveRole, "record_worker_location", "assignment", body.AssignmentID, true, nil)
	data := map[string]interface{}{
		"assignmentId": body.AssignmentID,
		"coordinate":   coordObj(body.Coordinate.Latitude, body.Coordinate.Longitude),
		"sequence":      body.Sequence,
		"recordedAt":    recordedAt.Format(time.RFC3339),
	}
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           string  `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	recordedAt, err := parseRFC3339(body.RecordedAt)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}
	var tMin, tMax float64
	var status string
	_ = pool.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c, status FROM samples WHERE sample_id=$1`, body.SampleID).Scan(&tMin, &tMax, &status)
	if status == "" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if status == "received" || status == "cancelled" {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusConflict, "terminal_sample", "sample is terminal")
		return
	}
	compliant := body.ObservedTemperatureC >= tMin && body.ObservedTemperatureC <= tMax
	checkpointID := newUUID()
	var locID interface{}
	if body.LocationID != "" {
		locID = body.LocationID
	}
	_, _ = pool.Exec(r.Context(), `INSERT INTO handling_checkpoints (checkpoint_id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		checkpointID, body.SampleID, strOrNull(body.AssignmentID), locID, body.ContainerType, body.ObservedTemperatureC, compliant, recordedAt)
	sampleStatus := status
	if !compliant {
		_, _ = pool.Exec(r.Context(), `UPDATE samples SET status='exception' WHERE sample_id=$1`, body.SampleID)
		sampleStatus = "exception"
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "handling_checkpoint", "sample", body.SampleID, true, map[string]interface{}{"compliant": compliant})
	data := map[string]interface{}{
		"checkpointId":  checkpointID,
		"sampleId":      body.SampleID,
		"compliant":     compliant,
		"sampleStatus":  sampleStatus,
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

