package main

import (
	"net/http"
	"time"
)

func dispatchRole(r *http.Request) (*requestUser, bool) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(nil, http.StatusConflict, "role_not_selected", "select a role first")
		return ru, false
	}
	if ru.ActiveRole != "dispatcher" && ru.ActiveRole != "administrator" {
		errResp(nil, http.StatusForbidden, "forbidden", "dispatcher role required")
		return ru, false
	}
	return ru, true
}

// writeConflictErr writes a 409 with idempotency storage.
func writeConflictErr(w http.ResponseWriter, key, userID, code, msg string) {
	writeErr(w, key, userID, http.StatusConflict, code, msg)
}

func handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	ru, ok := dispatchRole(r)
	if !ok {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		JourneyID          string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	if body.ExpectedPlanVersion < 1 {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_plan_version", "invalid plan version")
		return
	}
	var pv, status string
	var sampleID *string
	err := pool.QueryRow(r.Context(), `SELECT plan_version, status, sample_id::text FROM journeys WHERE journey_id=$1`, body.JourneyID).Scan(&pv, &status, &sampleID)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if pv != body.ExpectedPlanVersion {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "stale_plan", "plan version mismatch")
		return
	}
	if status == "completed" {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "completed_work_immutable", "journey completed")
		return
	}
	_, _ = pool.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE journey_id=$1`, body.JourneyID)
	_, _ = pool.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed')`, body.JourneyID)
	if sampleID != nil && *sampleID != "" {
		_, _ = pool.Exec(r.Context(), `UPDATE samples SET status='cancelled' WHERE sample_id=$1`, *sampleID)
	}
	sampleIDs := []string{}
	if sampleID != nil && *sampleID != "" {
		sampleIDs = append(sampleIDs, *sampleID)
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "cancel_journey", "journey", body.JourneyID, true, map[string]interface{}{"reason": body.Reason})
	emitEvent(r.Context(), "journey_cancelled", "journey", body.JourneyID, nil)
	data := map[string]interface{}{
		"journeyId": body.JourneyID,
		"status":    "cancelled",
		"sampleIds": sampleIDs,
	}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	ru, ok := dispatchRole(r)
	if !ok {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string    `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	if body.ExpectedPlanVersion < 1 {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_plan_version", "invalid plan version")
		return
	}
	var pv, status, routeMode string
	var sampleID *string
	err := pool.QueryRow(r.Context(), `SELECT plan_version, status, route_mode, sample_id::text FROM journeys WHERE journey_id=$1`, body.JourneyID).Scan(&pv, &status, &routeMode, &sampleID)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if pv != body.ExpectedPlanVersion {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "stale_plan", "plan version mismatch")
		return
	}
	if status == "completed" {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "completed_work_immutable", "journey completed")
		return
	}
	// create split journey with the moved sample
	splitID := newUUID()
	var movedSample interface{}
	if len(body.SampleIDs) > 0 {
		movedSample = body.SampleIDs[0]
	}
	_, _ = pool.Exec(r.Context(), `INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, sample_id) VALUES ($1,$2,1,$3,'planned',$4)`,
		splitID, body.JourneyID, routeMode, movedSample)
	_, _ = pool.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id=$1`, body.JourneyID)
	audit(r.Context(), ru.UserID, ru.ActiveRole, "split_journey", "journey", body.JourneyID, true, map[string]interface{}{"splitId": splitID})
	journey := buildJourneyPlan(r.Context(), body.JourneyID)
	split := buildJourneyPlan(r.Context(), splitID)
	data := map[string]interface{}{"journey": journey, "splitJourney": split}
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	ru, ok := dispatchRole(r)
	if !ok {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs     []string `json:"sourceJourneyIds"`
		IdempotencyKey      string    `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	if body.ExpectedPlanVersion < 1 {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_plan_version", "invalid plan version")
		return
	}
	var pv, status string
	err := pool.QueryRow(r.Context(), `SELECT plan_version, status FROM journeys WHERE journey_id=$1`, body.TargetJourneyID).Scan(&pv, &status)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if pv != body.ExpectedPlanVersion {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "stale_plan", "plan version mismatch")
		return
	}
	// mark source journeys merged into target
	for _, sid := range body.SourceJourneyIDs {
		_, _ = pool.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE journey_id=$1 AND status NOT IN ('completed')`, sid, body.TargetJourneyID)
		_, _ = pool.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE journey_id=$1`, sid)
	}
	_, _ = pool.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1, route_mode='batched' WHERE journey_id=$1`, body.TargetJourneyID)
	audit(r.Context(), ru.UserID, ru.ActiveRole, "merge_journeys", "journey", body.TargetJourneyID, true, map[string]interface{}{"sources": body.SourceJourneyIDs})
	data := buildJourneyPlan(r.Context(), body.TargetJourneyID)
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	ru, ok := dispatchRole(r)
	if !ok {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	if body.ExpectedPlanVersion < 1 {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_plan_version", "invalid plan version")
		return
	}
	var pv, status string
	var sampleID *string
	var deadline time.Time
	err := pool.QueryRow(r.Context(), `SELECT j.plan_version, j.status, j.sample_id::text, s.delivery_deadline FROM journeys j JOIN samples s ON s.sample_id=j.sample_id WHERE j.journey_id=$1`, body.JourneyID).Scan(&pv, &status, &sampleID, &deadline)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if pv != body.ExpectedPlanVersion {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "stale_plan", "plan version mismatch")
		return
	}
	if status == "completed" {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "completed_work_immutable", "journey completed")
		return
	}
	// attempt replan: simplest approach bumps plan version and re-marks planned
	_, _ = pool.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1, status='planned' WHERE journey_id=$1`, body.JourneyID)
	replanStatus := "replaced"
	data := map[string]interface{}{
		"journeyId":     body.JourneyID,
		"replanStatus":  replanStatus,
	}
	if sampleID != nil && *sampleID != "" {
		// re-plan journey
		var sampleTypeID string
		var requiresCooled bool
		_ = pool.QueryRow(r.Context(), `SELECT sample_type_id FROM samples WHERE sample_id=$1`, *sampleID).Scan(&sampleTypeID)
		_ = pool.QueryRow(r.Context(), `SELECT requires_cooled_route FROM sample_types WHERE sample_type_id=$1`, sampleTypeID).Scan(&requiresCooled)
		var lat, lng float64
		_ = pool.QueryRow(r.Context(), `SELECT COALESCE(latest_lat,origin_lat), COALESCE(latest_lng,origin_lng) FROM samples WHERE sample_id=$1`, *sampleID).Scan(&lat, &lng)
		pr, _ := planJourney(r.Context(), planInput{originLat: lat, originLng: lng, originType: "node", originNodeID: "", sampleTypeID: sampleTypeID, requiresCooled: requiresCooled, batchingAllowed: true, deadline: deadline, alreadySealed: true})
		if pr != nil {
			_, _ = pool.Exec(r.Context(), `UPDATE journeys SET sample_id=$2 WHERE journey_id=$1`, pr.journeyID, *sampleID)
			data["replacementPlanId"] = pr.journeyID
			data["replacementJourney"] = buildJourneyPlan(r.Context(), pr.journeyID)
		} else {
			replanStatus = "exception"
			data["replanStatus"] = replanStatus
		}
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "reroute_journey", "journey", body.JourneyID, true, map[string]interface{}{"reason": body.Reason})
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	ru, ok := dispatchRole(r)
	if !ok {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	if body.ExpectedPlanVersion < 1 {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_plan_version", "invalid plan version")
		return
	}
	validChanges := map[string]bool{"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true, "reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true, "cancel_work": true, "reroute": true, "replace_route": true}
	if !validChanges[body.ChangeType] {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_change_type", "unknown changeType")
		return
	}
	var pv, status string
	err := pool.QueryRow(r.Context(), `SELECT plan_version, status FROM journeys WHERE journey_id=$1`, body.JourneyID).Scan(&pv, &status)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if pv != body.ExpectedPlanVersion {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "stale_plan", "plan version mismatch")
		return
	}
	if status == "completed" {
		writeConflictErr(w, body.IdempotencyKey, ru.UserID, "completed_work_immutable", "journey completed")
		return
	}
	// apply worker replacement if specified
	if body.ChangeType == "replace_worker" || body.ChangeType == "reassign_worker" {
		if aid, ok := body.Changes["assignmentId"].(string); ok {
			if wid, ok2 := body.Changes["workerId"].(string); ok2 {
				_, _ = pool.Exec(r.Context(), `UPDATE assignments SET worker_id=$2, offered_worker_id=$2 WHERE assignment_id=$1 AND status NOT IN ('completed')`, aid, wid)
			}
		}
	}
	_, _ = pool.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id=$1`, body.JourneyID)
	audit(r.Context(), ru.UserID, ru.ActiveRole, "edit_active_plan", "journey", body.JourneyID, true, map[string]interface{}{"changeType": body.ChangeType})
	data := buildJourneyPlan(r.Context(), body.JourneyID)
	storeIdempotency(r.Context(), body.IdempotencyKey, ru.UserID, http.StatusCreated, map[string]interface{}{"data": data})
	jsonResp(w, http.StatusCreated, map[string]interface{}{"data": data})
}

func handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	ru, ok := dispatchRole(r)
	if !ok {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		ResourceType  string `json:"resourceType"`
		ResourceID    string `json:"resourceId"`
		Reason        string `json:"reason"`
		OccurredAt    string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := parseJSONBody(r, &body); err != nil {
		errResp(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if body.IdempotencyKey == "" {
		errResp(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if cached, code := checkIdempotency(r.Context(), body.IdempotencyKey, ru.UserID); cached != nil {
		jsonResp(w, code, cached)
		return
	}
	validTypes := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
	if !validTypes[body.ResourceType] {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_resource_type", "unknown resourceType")
		return
	}
	occurredAt, err := parseRFC3339(body.OccurredAt)
	if err != nil {
		writeErr(w, body.IdempotencyKey, ru.UserID, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}
	disruptionID := newUUID()
	// apply the disruption
	switch body.ResourceType {
	case "location", "node", "laboratory":
		_, _ = pool.Exec(r.Context(), `UPDATE locations SET active=false WHERE location_id=$1`, body.ResourceID)
	case "connection", "route":
		_, _ = pool.Exec(r.Context(), `UPDATE connections SET active=false WHERE connection_id=$1`, body.ResourceID)
	case "worker":
		_, _ = pool.Exec(r.Context(), `UPDATE users SET available=false WHERE user_id=$1`, body.ResourceID)
	case "capacity":
		_, _ = pool.Exec(r.Context(), `UPDATE capacity_pools SET capacity_units=0, cooled_capacity_units=0 WHERE resource_id=$1`, body.ResourceID)
	}
	recomputeServiceabilityAsync(r.Context())
	// affected samples
	affected := []string{}
	replIDs := []string{}
	replanStatus := "not_required"
	if body.ResourceType == "location" || body.ResourceType == "node" || body.ResourceType == "laboratory" {
		rows, _ := pool.Query(r.Context(), `SELECT DISTINCT s.sample_id::text FROM samples s JOIN assignments a ON a.sample_id=s.sample_id WHERE a.from_location_id=$1 OR a.to_location_id=$1 OR a.node_location_id=$1 OR a.laboratory_id=$1`, body.ResourceID)
		if rows != nil {
			for rows.Next() {
				var sid string
				_ = rows.Scan(&sid)
				affected = append(affected, sid)
			}
			rows.Close()
		}
	}
	if len(affected) > 0 {
		replanStatus = "exception"
	}
	_ = occurredAt
	audit(r.Context(), ru.UserID, ru.ActiveRole, "report_disruption", body.ResourceType, body.ResourceID, true, map[string]interface{}{"reason": body.Reason})
	data := map[string]interface{}{
		"disruptionId":        disruptionID,
		"affectedSampleIds":   affected,
		"replacementPlanIds":  replIDs,
		"replanStatus":        replanStatus,
	}
