func registerStatic(mux *http.ServeMux) {
	webDir := "/workspace/backend/web"
	if _, err := os.Stat(webDir); os.IsNotExist(err) {
		webDir = "/workspace/frontend/dist"
	}

	fs := http.FileServer(http.Dir(webDir))
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		// map assets proxy
		if strings.HasPrefix(r.URL.Path, "/map-assets/") {
			serveMapAssets(w, r)
			return
		}
		if strings.HasPrefix(r.URL.Path, "/api/") || r.URL.Path == "/ready" {
			http.NotFound(w, r)
			return
		}
		// SPA fallback
		full := filepath.Join(webDir, filepath.Clean(r.URL.Path))
		if r.URL.Path != "/" {
			if info, err := os.Stat(full); err != nil || info.IsDir() {
				r2 := r.Clone(r.Context())
				r2.URL.Path = "/"
				fs.ServeHTTP(w, r2)
				return
			}
		}
		fs.ServeHTTP(w, r)
	})
}

func serveMapAssets(w http.ResponseWriter, r *http.Request) {
	rel := strings.TrimPrefix(r.URL.Path, "/map-assets/")
	p := filepath.Join(mapAssetsDir, filepath.Clean("/"+rel))
	if !strings.HasPrefix(p, mapAssetsDir) {
		http.NotFound(w, r)
		return
	}
	if info, err := os.Stat(p); err != nil || info.IsDir() {
		http.NotFound(w, r)
		return
	}
	switch strings.ToLower(filepath.Ext(p)) {
	case ".pmtiles":
		w.Header().Set("Content-Type", "application/octet-stream")
	case ".json":
		w.Header().Set("Content-Type", "application/json")
	case ".png":
		w.Header().Set("Content-Type", "image/png")
	case ".pbf", ".gz":
		w.Header().Set("Content-Type", "application/x-protobuf")
	}
	http.ServeFile(w, r, p)
