  active boolean NOT NULL DEFAULT true,
  expires_at timestamptz
);

CREATE TABLE IF NOT EXISTS sessions (
  token text PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  active_role text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);

CREATE TABLE IF NOT EXISTS sample_types (
  sample_type_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text UNIQUE NOT NULL,
  qualified_collector_required boolean NOT NULL DEFAULT true,
  required_qualification text NOT NULL DEFAULT '',
  container_type text NOT NULL,
  temperature_min_c double precision NOT NULL,
  temperature_max_c double precision NOT NULL,
  incompatible_sample_types text[] NOT NULL DEFAULT '{}',
  requires_cooled_route boolean NOT NULL DEFAULT false,
  batching_allowed boolean NOT NULL DEFAULT true,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS locations (
  location_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  latitude double precision NOT NULL,
  longitude double precision NOT NULL,
  coverage_km double precision NOT NULL DEFAULT 0,
  handling_minutes integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  fn_collection_point boolean NOT NULL DEFAULT false,
  fn_transfer_point boolean NOT NULL DEFAULT false,
  fn_hub boolean NOT NULL DEFAULT false,
  fn_laboratory boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS laboratory_acceptance (
  acceptance_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  laboratory_id uuid NOT NULL REFERENCES locations(location_id) ON DELETE CASCADE,
  sample_type_id uuid NOT NULL REFERENCES sample_types(sample_type_id) ON DELETE CASCADE,
  accepts boolean NOT NULL DEFAULT true,
  UNIQUE(laboratory_id, sample_type_id)
);

CREATE TABLE IF NOT EXISTS connections (
  connection_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  from_location_id uuid NOT NULL REFERENCES locations(location_id) ON DELETE CASCADE,
  to_location_id uuid NOT NULL REFERENCES locations(location_id) ON DELETE CASCADE,
  travel_minutes integer NOT NULL,
  cost_units double precision NOT NULL DEFAULT 0,
  cooled boolean NOT NULL DEFAULT false,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS capacity_pools (
  pool_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  resource_id uuid NOT NULL,
  resource_kind text NOT NULL,
  capacity_units integer NOT NULL DEFAULT 0,
  cooled_capacity_units integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(resource_id)
);

CREATE TABLE IF NOT EXISTS requests (
  request_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  requester_id uuid NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  sample_id uuid NOT NULL,
  origin_type text NOT NULL,
  origin_location_id uuid,
  origin_lat double precision,
  origin_lng double precision,
  requested_at timestamptz NOT NULL,
  earliest_collection_at timestamptz,
  latest_collection_at timestamptz,
  delivery_deadline timestamptz NOT NULL,
  sample_type_id uuid NOT NULL REFERENCES sample_types(sample_type_id),
  container_type text NOT NULL,
  temperature_min_c double precision NOT NULL,
  temperature_max_c double precision NOT NULL,
  incompatible_sample_types text[] NOT NULL DEFAULT '{}',
  already_sealed boolean NOT NULL DEFAULT false,
  serviceable boolean NOT NULL DEFAULT true,
  serviceability_reason text NOT NULL DEFAULT 'serviceable',
  target_laboratory_id uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS samples (
  sample_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id uuid NOT NULL REFERENCES requests(request_id) ON DELETE CASCADE,
  requester_id uuid NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  sample_type_id uuid NOT NULL REFERENCES sample_types(sample_type_id),
  status text NOT NULL DEFAULT 'requested',
  sealed boolean NOT NULL DEFAULT false,
  current_holder_id uuid,
  latest_lat double precision,
  latest_lng double precision,
  location_recorded_at timestamptz,
  origin_type text NOT NULL,
  origin_lat double precision,
  origin_lng double precision,
  delivery_deadline timestamptz NOT NULL,
  container_type text NOT NULL,
  temperature_min_c double precision NOT NULL,
  temperature_max_c double precision NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS journeys (
  journey_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  parent_journey_id uuid,
  plan_version integer NOT NULL DEFAULT 1,
  route_mode text NOT NULL DEFAULT 'direct',
  status text NOT NULL DEFAULT 'planned',
  sample_id uuid REFERENCES samples(sample_id) ON DELETE CASCADE,
  target_laboratory_id uuid,
  estimated_delivery_at timestamptz,
  total_cost_units double precision DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS journey_stops (
  stop_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  journey_id uuid NOT NULL REFERENCES journeys(journey_id) ON DELETE CASCADE,
  location_id uuid NOT NULL REFERENCES locations(location_id),
  stop_type text NOT NULL,
  sequence integer NOT NULL,
  estimated_at timestamptz NOT NULL,
  dwell_minutes integer NOT NULL DEFAULT 0,
  completed_at timestamptz
);

CREATE TABLE IF NOT EXISTS assignments (
  assignment_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  journey_id uuid NOT NULL REFERENCES journeys(journey_id) ON DELETE CASCADE,
  sample_id uuid REFERENCES samples(sample_id) ON DELETE CASCADE,
  kind text NOT NULL,
  sequence integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'offered',
  from_location_id uuid,
  to_location_id uuid,
  node_location_id uuid,
  laboratory_id uuid,
  worker_id uuid,
  offered_worker_id uuid,
  offer_expires_at timestamptz,
  accepted_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_assignments_worker ON assignments(worker_id);
CREATE INDEX IF NOT EXISTS idx_assignments_offered ON assignments(offered_worker_id) WHERE status='offered';
CREATE INDEX IF NOT EXISTS idx_assignments_journey ON assignments(journey_id);
CREATE INDEX IF NOT EXISTS idx_assignments_sample ON assignments(sample_id);

CREATE TABLE IF NOT EXISTS handoffs (
  handoff_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id uuid NOT NULL REFERENCES samples(sample_id) ON DELETE CASCADE,
  from_assignment_id uuid NOT NULL REFERENCES assignments(assignment_id) ON DELETE CASCADE,
  to_assignment_id uuid NOT NULL REFERENCES assignments(assignment_id) ON DELETE CASCADE,
  sender_id uuid NOT NULL,
  receiver_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'pending',
  sender_confirmed boolean NOT NULL DEFAULT false,
  receiver_confirmed boolean NOT NULL DEFAULT false,
  initiated_at timestamptz NOT NULL DEFAULT now(),
  confirmed_at timestamptz
);

CREATE TABLE IF NOT EXISTS capacity_reservations (
  reservation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  resource_id uuid NOT NULL,
  journey_id uuid NOT NULL REFERENCES journeys(journey_id) ON DELETE CASCADE,
  assignment_id uuid REFERENCES assignments(assignment_id) ON DELETE CASCADE,
  sample_id uuid REFERENCES samples(sample_id) ON DELETE CASCADE,
  units integer NOT NULL DEFAULT 1,
  cooled boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_reservations_resource ON capacity_reservations(resource_id);

CREATE TABLE IF NOT EXISTS worker_locations (
  id bigserial PRIMARY KEY,
  assignment_id uuid NOT NULL,
  worker_id uuid NOT NULL,
  latitude double precision NOT NULL,
  longitude double precision NOT NULL,
  sequence integer NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_worker_loc_assignment ON worker_locations(assignment_id);

CREATE TABLE IF NOT EXISTS handling_checkpoints (
  checkpoint_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id uuid NOT NULL REFERENCES samples(sample_id) ON DELETE CASCADE,
  assignment_id uuid,
  location_id uuid,
  container_type text NOT NULL,
  observed_temperature_c double precision NOT NULL,
  compliant boolean NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS idempotency_keys (
  key text PRIMARY KEY,
  user_id uuid,
  endpoint text,
  response_body jsonb,
  status_code integer,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS audit_log (
  audit_id bigserial PRIMARY KEY,
  actor_id uuid,
  actor_role text,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id text NOT NULL,
  success boolean NOT NULL DEFAULT true,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  details jsonb NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_log(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_log(actor_id);
CREATE INDEX IF NOT EXISTS idx_audit_action ON audit_log(action);
CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_log(occurred_at);

CREATE TABLE IF NOT EXISTS realtime_events (
  event_id bigserial PRIMARY KEY,
  type text NOT NULL,
  entity_type text NOT NULL,
  entity_id text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_events_created ON realtime_events(created_at);

CREATE TABLE IF NOT EXISTS serviceability_versions (
  version integer PRIMARY KEY,
  status text NOT NULL,
  network_revision integer NOT NULL DEFAULT 1,
  computed_at timestamptz NOT NULL DEFAULT now(),
  regions jsonb NOT NULL DEFAULT '[]',
  active_collection_point_count integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS meta (
  key text PRIMARY KEY,
  value text NOT NULL
);
`

const resetDropSQL = `
DROP TABLE IF EXISTS meta CASCADE;
DROP TABLE IF EXISTS serviceability_versions CASCADE;
DROP TABLE IF EXISTS realtime_events CASCADE;
DROP TABLE IF EXISTS audit_log CASCADE;
DROP TABLE IF EXISTS idempotency_keys CASCADE;
DROP TABLE IF EXISTS handling_checkpoints CASCADE;
DROP TABLE IF EXISTS worker_locations CASCADE;
DROP TABLE IF EXISTS capacity_reservations CASCADE;
DROP TABLE IF EXISTS handoffs CASCADE;
DROP TABLE IF EXISTS assignments CASCADE;
DROP TABLE IF EXISTS journey_stops CASCADE;
DROP TABLE IF EXISTS journeys CASCADE;
DROP TABLE IF EXISTS samples CASCADE;
DROP TABLE IF EXISTS requests CASCADE;
DROP TABLE IF EXISTS capacity_pools CASCADE;
DROP TABLE IF EXISTS connections CASCADE;
DROP TABLE IF EXISTS laboratory_acceptance CASCADE;
DROP TABLE IF EXISTS locations CASCADE;
DROP TABLE IF EXISTS sample_types CASCADE;
DROP TABLE IF EXISTS sessions CASCADE;
DROP TABLE IF EXISTS certifications CASCADE;
DROP TABLE IF EXISTS users CASCADE;
`

func openDB(ctx context.Context) error {
	dsn := envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable")
	p, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return fmt.Errorf("pgxpool: %w", err)
	}
	pool = p

	redisURL := envOr("REDIS_URL", "redis://127.0.0.1:6379/0")
	opt, err := redis.ParseURL(redisURL)
	if err != nil {
		return fmt.Errorf("redis parse: %w", err)
	}
	rdb = redis.NewClient(opt)
	if err := rdb.Ping(ctx).Err(); err != nil {
		return fmt.Errorf("redis ping: %w", err)
	}
	return nil
}

func closeDB() {
	if pool != nil {
		pool.Close()
	}
	if rdb != nil {
		_ = rdb.Close()
	}
}

func runMigrate(ctx context.Context) error {
	if err := openDB(ctx); err != nil {
		return err
	}
	defer closeDB()
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := seedDefaults(ctx, false); err != nil {
		return fmt.Errorf("seed: %w", err)
	}
	if err := recomputeServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	return nil
}

func runReset(ctx context.Context) error {
	if err := openDB(ctx); err != nil {
		return err
	}
	defer closeDB()
	if _, err := pool.Exec(ctx, resetDropSQL); err != nil {
		return fmt.Errorf("drop: %w", err)
	}
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := seedDefaults(ctx, true); err != nil {
		return fmt.Errorf("seed: %w", err)
	}
	if err := recomputeServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	return nil
}

func envOr(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}

func hashPassword(password, salt string) string {
	h := sha256.Sum256([]byte(salt + ":" + password))
	return hex.EncodeToString(h[:])
}

var _ = strings.TrimSpace
var _ = time.Now

